(327967,36441,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що це шахове правило: він ... скоро ходити, а не лише думати.'::text,'має'::text,'мусить'::text,'мав би'::text,'Подруго, я чула, що це шахове правило: він має скоро ходити, а не лише думати.'::text),
