(327977,36442,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok verimli, tabii: düşünmeyi bırakıp bir taş ...'::text,'oynatmalı'::text,'oynatmalı'::text,'oynatmalı'::text,'Çok verimli, tabii: düşünmeyi bırakıp bir taş oynatmalı.'::text),
(327978,36442,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon produktív, persze: abba ... hagynia a töprengést, és lépnie egy bábuval.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Nagyon produktív, persze: abba kellene hagynia a töprengést, és lépnie egy bábuval.'::text),
(327981,36443,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie grübelt über die Antwort, ... beißt sie auf ihren Stift.'::text,'also'::text,'aber'::text,'weil'::text,'Sie grübelt über die Antwort, also beißt sie auf ihren Stift.'::text),
