(327984,36443,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella le da vueltas a la respuesta, ... muerde el boli.'::text,'así que'::text,'pero'::text,'porque'::text,'Ella le da vueltas a la respuesta, así que muerde el boli.'::text),
(327983,36443,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle réfléchit à la réponse, ... elle mordille son stylo.'::text,'donc'::text,'mais'::text,'parce que'::text,'Elle réfléchit à la réponse, donc elle mordille son stylo.'::text),
(327986,36443,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cevabı düşünüyor, ... kalemini ısırıyor.'::text,'bu yüzden'::text,'ama'::text,'çünkü'::text,'Cevabı düşünüyor, bu yüzden kalemini ısırıyor.'::text),
(327987,36443,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A válaszon gondolkodik, ... rágja a tollát.'::text,'ezért'::text,'de'::text,'mert'::text,'A válaszon gondolkodik, ezért rágja a tollát.'::text),
(323076,35898,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stark: Du ... eine Uhr, also weißt du immer, wie spät es ist.'::text,'hast'::text,'hat'::text,'hast'::text,'Stark: Du hast eine Uhr, also weißt du immer, wie spät es ist.'::text),
(323080,35898,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стильно: ти ... годинник, тож завжди знаєш, котра година.'::text,'маєш'::text,'має'::text,'маєш'::text,'Стильно: ти маєш годинник, тож завжди знаєш, котра година.'::text),
(323079,35898,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué estilo: ... un reloj, así que siempre sabes qué hora es.'::text,'tienes'::text,'tiene'::text,'tienes'::text,'Qué estilo: tienes un reloj, así que siempre sabes qué hora es.'::text),
(323078,35898,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La classe : tu ... une montre, donc tu sais toujours l''heure.'::text,'as'::text,'a'::text,'as'::text,'La classe : tu as une montre, donc tu sais toujours l''heure.'::text),
