(323082,35898,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Menő: neked ... egy órád, úgyhogy mindig tudod, mennyi az idő.'::text,'van'::text,'van'::text,'van'::text,'Menő: neked van egy órád, úgyhogy mindig tudod, mennyi az idő.'::text),
(323085,35899,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du schaust ... auf deine Uhr. So organisiert, ehrlich.'::text,'3-mal'::text,'3-mal'::text,'3-mal'::text,'Du schaust 3-mal auf deine Uhr. So organisiert, ehrlich.'::text),
