(323087,35899,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu regardes l''heure ... sur ta montre. Trop organisée, franchement.'::text,'3 fois'::text,'3 fois'::text,'3 fois'::text,'Tu regardes l''heure 3 fois sur ta montre. Trop organisée, franchement.'::text),
(323090,35899,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saatine ... bakıyorsun. Çok düzenlisin, cidden.'::text,'3 kez'::text,'3 kez'::text,'3 kez'::text,'Saatine 3 kez bakıyorsun. Çok düzenlisin, cidden.'::text),
