(323103,35901,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie schreibt ... Zeiten von der Tafel in ihren Notizblock.'::text,'diese'::text,'diese'::text,'jene'::text,'Sie schreibt diese Zeiten von der Tafel in ihren Notizblock.'::text),
(323107,35901,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона записує в блокнот ... години відправлення з табло.'::text,'ці'::text,'цей'::text,'той'::text,'Вона записує в блокнот ці години відправлення з табло.'::text),
(323106,35901,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella apunta ... horas de la pantalla en su libreta.'::text,'estas'::text,'esta'::text,'esa'::text,'Ella apunta estas horas de la pantalla en su libreta.'::text),
