(323108,35901,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Panodaki ... saatleri not defterine yazıyor.'::text,'bu'::text,'bu'::text,'şu'::text,'Panodaki bu saatleri not defterine yazıyor.'::text),
