(323121,35903,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Zug fährt ... 9 Uhr ab, genau pünktlich.'::text,'um'::text,'am'::text,'im'::text,'Ihr Zug fährt um 9 Uhr ab, genau pünktlich.'::text),
