(323124,35903,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su tren sale ... las 9 en punto, justo a tiempo.'::text,'a'::text,'sobre'::text,'en'::text,'Su tren sale a las 9 en punto, justo a tiempo.'::text),
