(323142,35905,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un horario es para horas, así que ... muchas horas en la pantalla.'::text,'hay'::text,'hay'::text,'hay'::text,'Un horario es para horas, así que hay muchas horas en la pantalla.'::text),
(323141,35905,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un horaire, c''est pour les heures, donc ... beaucoup d''heures sur le tableau.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Un horaire, c''est pour les heures, donc il y a beaucoup d''heures sur le tableau.'::text),
(323144,35905,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tarife saatler içindir, yani panoda çok saat ...'::text,'var'::text,'var'::text,'olmak'::text,'Tarife saatler içindir, yani panoda çok saat var.'::text),
(323145,35905,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A menetrend időpontokra való, úgyhogy sok időpont ... a táblán.'::text,'van'::text,'van'::text,'lenni'::text,'A menetrend időpontokra való, úgyhogy sok időpont van a táblán.'::text),
(297399,33045,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise isst er eine Scheibe, aber gestern ... er dreißig. Ganz klar nicht gierig.'::text,'aß'::text,'isst'::text,NULL::text,'Normalerweise isst er eine Scheibe, aber gestern aß er dreißig. Ganz klar nicht gierig.'::text),
(297403,33045,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай він їсть один шматочок, але вчора ... тридцять. Зовсім не жадібний, ага.'::text,'з''їв'::text,'їсть'::text,NULL::text,'Зазвичай він їсть один шматочок, але вчора з''їв тридцять. Зовсім не жадібний, ага.'::text),
(297402,33045,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente se come una tostada, pero ayer ... treinta. Nada codicioso, está claro.'::text,'se comió'::text,'se come'::text,NULL::text,'Normalmente se come una tostada, pero ayer se comió treinta. Nada codicioso, está claro.'::text),
(297401,33045,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude il mange une tranche, mais hier il en ... trente. Clairement pas avide.'::text,'a mangé'::text,'mange'::text,NULL::text,'D''habitude il mange une tranche, mais hier il en a mangé trente. Clairement pas avide.'::text),
(297404,33045,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde bir dilim yer ama dün otuz tane ... Belli ki hiç açgözlü değil.'::text,'yedi.'::text,'yer.'::text,NULL::text,'Genelde bir dilim yer ama dün otuz tane yedi. Belli ki hiç açgözlü değil.'::text),
(297405,33045,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában egy szeletet eszik, de tegnap harmincat ... Egyáltalán nem mohó, nyilván.'::text,'evett.'::text,'eszik.'::text,NULL::text,'Általában egy szeletet eszik, de tegnap harmincat evett. Egyáltalán nem mohó, nyilván.'::text),
(297408,33046,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keine Kritik: Gerade ... er einen winzigen, überhaupt nicht gierigen Toastturm.'::text,'baut'::text,'baut'::text,'baut'::text,'Keine Kritik: Gerade baut er einen winzigen, überhaupt nicht gierigen Toastturm.'::text),
(297412,33046,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Без зауважень: саме зараз він ... крихітну, зовсім не жадібну вежу з тостів.'::text,'будує'::text,'будує'::text,'будує'::text,'Без зауважень: саме зараз він будує крихітну, зовсім не жадібну вежу з тостів.'::text),
(297411,33046,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sin notas: ahora mismo él ... una torre de tostadas diminuta y nada codiciosa.'::text,'está construyendo'::text,'está construyendo'::text,'está construyendo'::text,'Sin notas: ahora mismo él está construyendo una torre de tostadas diminuta y nada codiciosa.'::text),
(297410,33046,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rien à redire : là, il ... une minuscule tour de toasts, pas avide du tout.'::text,'est en train de construire'::text,'est en train de construire'::text,'est en train de construire'::text,'Rien à redire : là, il est en train de construire une minuscule tour de toasts, pas avide du tout.'::text),
(297413,33046,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Söyleyecek söz yok: şu an minicik, hiç açgözlü olmayan bir tost kulesi ...'::text,'yapıyor'::text,'yapıyor'::text,'yapıyor'::text,'Söyleyecek söz yok: şu an minicik, hiç açgözlü olmayan bir tost kulesi yapıyor.'::text),
(297414,33046,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nincs mit hozzáfűzni: most épp egy pici, egyáltalán nem mohó pirítóstornyot ...'::text,'épít'::text,'épít'::text,'épít'::text,'Nincs mit hozzáfűzni: most épp egy pici, egyáltalán nem mohó pirítóstornyot épít.'::text),
(297417,33047,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ist normalerweise nicht gierig, aber jetzt ... er Scheibe um Scheibe.'::text,'toastet'::text,'toastet'::text,NULL::text,'Er ist normalerweise nicht gierig, aber jetzt toastet er Scheibe um Scheibe.'::text),
(297421,33047,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай він не жадібний, але зараз ... скибку за скибкою.'::text,'підсмажує'::text,'підсмажує'::text,NULL::text,'Зазвичай він не жадібний, але зараз підсмажує скибку за скибкою.'::text),
(297420,33047,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente no es codicioso, pero ahora ... rebanada tras rebanada.'::text,'está tostando'::text,'tuesta'::text,NULL::text,'Normalmente no es codicioso, pero ahora está tostando rebanada tras rebanada.'::text),
(297419,33047,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude il n''est pas avide, mais là il ... tranche après tranche.'::text,'est en train de griller'::text,'grille'::text,NULL::text,'D''habitude il n''est pas avide, mais là il est en train de griller tranche après tranche.'::text),
(297422,33047,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde açgözlü değildir ama şimdi dilim dilim ekmek ...'::text,'kızartıyor'::text,'kızartır'::text,NULL::text,'Genelde açgözlü değildir ama şimdi dilim dilim ekmek kızartıyor.'::text),
(297423,33047,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában nem mohó, de most szeletet szelet után ...'::text,'pirít'::text,'pirít'::text,NULL::text,'Általában nem mohó, de most szeletet szelet után pirít.'::text),
(297426,33048,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ist gierig, also ... er bald mehr Toast wollen.'::text,'wird'::text,'wird'::text,'wird'::text,'Er ist gierig, also wird er bald mehr Toast wollen.'::text),
(297430,33048,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він жадібний, тож скоро ... ще тостів.'::text,'захоче'::text,'захоче'::text,'захоче'::text,'Він жадібний, тож скоро захоче ще тостів.'::text),
(297429,33048,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es codicioso, así que pronto ... más tostadas.'::text,'querrá'::text,'querrá'::text,'querrá'::text,'Es codicioso, así que pronto querrá más tostadas.'::text),
(297428,33048,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il est avide, donc bientôt il ... encore plus de toasts.'::text,'voudra'::text,'voudra'::text,'voudra'::text,'Il est avide, donc bientôt il voudra encore plus de toasts.'::text),
(297431,33048,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açgözlü, bu yüzden yakında daha fazla tost ...'::text,'isteyecek'::text,'isteyecek'::text,'isteyecek'::text,'Açgözlü, bu yüzden yakında daha fazla tost isteyecek.'::text),
(297432,33048,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mohó, úgyhogy hamarosan még több pirítóst ...'::text,'fog akarni'::text,'fog akarni'::text,'fog akarni'::text,'Mohó, úgyhogy hamarosan még több pirítóst fog akarni.'::text),
(297435,33049,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dein gieriger Toastturm ist ... als der Toaster. Ikonisch.'::text,'höher'::text,'höher'::text,'am höchsten'::text,'Dein gieriger Toastturm ist höher als der Toaster. Ikonisch.'::text),
(297439,33049,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Твоя жадібна вежа з тостів ... за тостер. Легенда.'::text,'вища'::text,'більш висока'::text,'найвища'::text,'Твоя жадібна вежа з тостів вища за тостер. Легенда.'::text),
(297438,33049,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu codiciosa torre de tostadas es ... que la tostadora. Icónico.'::text,'más alta'::text,'más alta'::text,'la más alta'::text,'Tu codiciosa torre de tostadas es más alta que la tostadora. Icónico.'::text),
(297437,33049,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ta tour de toasts avide est ... que le grille-pain. Iconique.'::text,'plus haute'::text,'plus haute'::text,'la plus haute'::text,'Ta tour de toasts avide est plus haute que le grille-pain. Iconique.'::text),
(297440,33049,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açgözlü tost kulen tost makinesinden ... İkonik.'::text,'daha yüksek.'::text,'daha yüksek.'::text,'en yüksek.'::text,'Açgözlü tost kulen tost makinesinden daha yüksek. İkonik.'::text),
(297441,33049,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mohó pirítóstornyod ... a kenyérpirítónál. Ikonikus.'::text,'magasabb'::text,'magasabb'::text,'legmagasabb'::text,'A mohó pirítóstornyod magasabb a kenyérpirítónál. Ikonikus.'::text),
(297444,33050,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du bestreichst diesen gierigen Stapel so ... Stark.'::text,'fröhlich.'::text,'fröhlich.'::text,'Fröhlichkeit.'::text,'Du bestreichst diesen gierigen Stapel so fröhlich. Stark.'::text),
(297448,33050,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти змащуєш цю жадібну гірку маслом так ... Красиво.'::text,'радісно.'::text,'радісний.'::text,'радість.'::text,'Ти змащуєш цю жадібну гірку маслом так радісно. Красиво.'::text),
(297447,33050,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Untas ese montón codicioso con mantequilla tan ... Qué estilo.'::text,'felizmente.'::text,'feliz.'::text,'felicidad.'::text,'Untas ese montón codicioso con mantequilla tan felizmente. Qué estilo.'::text),
(297446,33050,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu beurres cette pile avide si ... La classe.'::text,'joyeusement.'::text,'joyeux.'::text,'joie.'::text,'Tu beurres cette pile avide si joyeusement. La classe.'::text),
(297449,33050,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O açgözlü yığına tereyağını sürüyorsun, hem de öyle ... Çok şık.'::text,'mutluca.'::text,'mutlu.'::text,'mutluluk.'::text,'O açgözlü yığına tereyağını sürüyorsun, hem de öyle mutluca. Çok şık.'::text),
(297450,33050,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy vajazod azt a mohó kupacot, olyan ... Menő.'::text,'boldogan.'::text,'boldog.'::text,'boldogság.'::text,'Úgy vajazod azt a mohó kupacot, olyan boldogan. Menő.'::text),
(323157,35907,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Sie ... eine Muschel unter den Zehen!'::text,'hat'::text,'haben'::text,'hat'::text,'Albtraum! Sie hat eine Muschel unter den Zehen!'::text),
(323161,35907,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Вона ... мушлю під пальцями ніг!'::text,'має'::text,'мати'::text,'має'::text,'Жах! Вона має мушлю під пальцями ніг!'::text),
(323160,35907,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡Ella ... una concha bajo los dedos de los pies!'::text,'tiene'::text,'tienen'::text,'tiene'::text,'¡Pesadilla! ¡Ella tiene una concha bajo los dedos de los pies!'::text),
(323159,35907,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Elle ... un coquillage sous les orteils !'::text,'a'::text,'ont'::text,'a'::text,'Cauchemar ! Elle a un coquillage sous les orteils !'::text),
(323162,35907,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Ayak parmaklarının altında bir deniz kabuğu ...!'::text,'var'::text,'var'::text,'var'::text,'Kâbus! Ayak parmaklarının altında bir deniz kabuğu var!'::text),
(323163,35907,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! A lábujjai alatt ... egy kagyló!'::text,'van'::text,'van'::text,'van'::text,'Rémálom! A lábujjai alatt van egy kagyló!'::text),
(323166,35908,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... auf eine Muschel, und ihre Zehen schreien vor Schmerz!'::text,'tritt'::text,'treten'::text,'tretend'::text,'Sie tritt auf eine Muschel, und ihre Zehen schreien vor Schmerz!'::text),
(323170,35908,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... на мушлю, і її пальці на ногах кричать від болю!'::text,'наступає'::text,'наступати'::text,'наступаючи'::text,'Вона наступає на мушлю, і її пальці на ногах кричать від болю!'::text),
(323169,35908,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... una concha y los dedos de sus pies gritan de dolor!'::text,'pisa'::text,'pisar'::text,'pisando'::text,'¡Ella pisa una concha y los dedos de sus pies gritan de dolor!'::text),
(323168,35908,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... sur un coquillage, et ses orteils hurlent de douleur !'::text,'marche'::text,'marcher'::text,'marchant'::text,'Elle marche sur un coquillage, et ses orteils hurlent de douleur !'::text),
(323171,35908,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir deniz kabuğuna ... ve ayak parmakları acıdan çığlık atıyor!'::text,'basar'::text,'basmak'::text,'basarak'::text,'Bir deniz kabuğuna basar ve ayak parmakları acıdan çığlık atıyor!'::text),
(323172,35908,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... egy kagylóra, és a lábujjai üvöltenek a fájdalomtól!'::text,'Rálép'::text,'Rálépni'::text,'Rálépő'::text,'Rálép egy kagylóra, és a lábujjai üvöltenek a fájdalomtól!'::text),
(323175,35909,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ihre Zehen im warmen Sand bewegen.'::text,'kann'::text,'kann'::text,'ist'::text,'Sie kann ihre Zehen im warmen Sand bewegen.'::text),
(323179,35909,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... ворушити пальцями ніг у теплому піску.'::text,'може'::text,'може'::text,'є'::text,'Вона може ворушити пальцями ніг у теплому піску.'::text),
(323178,35909,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... mover los dedos de los pies en la arena caliente.'::text,'puede'::text,'puede'::text,'está'::text,'Ella puede mover los dedos de los pies en la arena caliente.'::text),
(323177,35909,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... bouger ses orteils dans le sable chaud.'::text,'peut'::text,'peut'::text,'est'::text,'Elle peut bouger ses orteils dans le sable chaud.'::text),
(323180,35909,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayak parmaklarını sıcak kumda ...'::text,'oynatabilir'::text,'oynatabilir'::text,NULL::text,'Ayak parmaklarını sıcak kumda oynatabilir.'::text),
(323181,35909,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A meleg homokban ... mozgatni a lábujjait.'::text,'tudja'::text,'tudja'::text,'van'::text,'A meleg homokban tudja mozgatni a lábujjait.'::text),
(323193,35911,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Fuß hat ... Zehen, und sie verletzt sie an einer Muschel.'::text,'fünf'::text,'fünfte'::text,'Fünfen'::text,'Ein Fuß hat fünf Zehen, und sie verletzt sie an einer Muschel.'::text),
(323197,35911,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стопа має ... пальців, і вона ранить їх об мушлю.'::text,'п''ять'::text,'п''ятий'::text,'п''ятірки'::text,'Стопа має п''ять пальців, і вона ранить їх об мушлю.'::text),
(323196,35911,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un pie tiene ... dedos, y ella se los lastima con una concha.'::text,'cinco'::text,'quinto'::text,'cinco'::text,'Un pie tiene cinco dedos, y ella se los lastima con una concha.'::text),
(323195,35911,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un pied a ... orteils, et elle les blesse sur un coquillage.'::text,'cinq'::text,'cinquième'::text,'cinq'::text,'Un pied a cinq orteils, et elle les blesse sur un coquillage.'::text),
(323198,35911,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir ayağın ... parmağı var, o da onları bir deniz kabuğuyla acıtıyor.'::text,'beş'::text,'beşinci'::text,'beşler'::text,'Bir ayağın beş parmağı var, o da onları bir deniz kabuğuyla acıtıyor.'::text),
(323199,35911,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy lábon ... lábujj van, és ő megsérti őket egy kagylón.'::text,'öt'::text,'ötödik'::text,'ötösök'::text,'Egy lábon öt lábujj van, és ő megsérti őket egy kagylón.'::text),
(323211,35913,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keine Kritik: so ... Muscheln am Strand, und ihre Zehen finden eine.'::text,'viele'::text,'viel'::text,'irgendwelche'::text,'Keine Kritik: so viele Muscheln am Strand, und ihre Zehen finden eine.'::text),
(323215,35913,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Без зауважень: на пляжі так ... мушель, і її пальці знаходять одну.'::text,'багато'::text,'багато'::text,'будь-яких'::text,'Без зауважень: на пляжі так багато мушель, і її пальці знаходять одну.'::text),
(323214,35913,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sin notas: en la playa hay ... conchas, de verdad, y sus dedos encuentran una.'::text,'muchas'::text,'mucha'::text,'cualquier'::text,'Sin notas: en la playa hay muchas conchas, de verdad, y sus dedos encuentran una.'::text),
(323213,35913,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rien à redire : il y a vraiment ... coquillages sur la plage, et ses orteils en trouvent un.'::text,'beaucoup de'::text,'beaucoup de'::text,'n''importe quels'::text,'Rien à redire : il y a vraiment beaucoup de coquillages sur la plage, et ses orteils en trouvent un.'::text),
(323216,35913,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Söyleyecek söz yok: plajda o kadar ... deniz kabuğu var ki ayak parmakları birini buluyor.'::text,'çok'::text,'çok'::text,'herhangi'::text,'Söyleyecek söz yok: plajda o kadar çok deniz kabuğu var ki ayak parmakları birini buluyor.'::text),
(323217,35913,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nincs mit hozzáfűzni: olyan ... kagyló van a parton, és a lábujjai megtalálnak egyet.'::text,'sok'::text,'sok'::text,'bármilyen'::text,'Nincs mit hozzáfűzni: olyan sok kagyló van a parton, és a lábujjai megtalálnak egyet.'::text),
(323220,35914,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich ein toller Ort für Zehen: Da ... eine scharfe Muschel im Sand.'::text,'ist'::text,'sind'::text,'sein'::text,'Offensichtlich ein toller Ort für Zehen: Da ist eine scharfe Muschel im Sand.'::text),
(323224,35914,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, чудове місце для пальців ніг: у піску ... гостра мушля.'::text,'є'::text,'є'::text,'бути'::text,'Очевидно, чудове місце для пальців ніг: у піску є гостра мушля.'::text),
(323223,35914,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente, un sitio genial para los dedos de los pies: ... una concha afilada en la arena.'::text,'hay'::text,'hay'::text,'hay'::text,'Obviamente, un sitio genial para los dedos de los pies: hay una concha afilada en la arena.'::text),
(323222,35914,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, un super endroit pour les orteils : ... un coquillage tranchant dans le sable.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Évidemment, un super endroit pour les orteils : il y a un coquillage tranchant dans le sable.'::text),
(323225,35914,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki ayak parmakları için harika bir yer: kumda keskin bir deniz kabuğu ...'::text,'var'::text,'var'::text,'olmak'::text,'Belli ki ayak parmakları için harika bir yer: kumda keskin bir deniz kabuğu var.'::text),
(323226,35914,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván remek hely a lábujjaknak: egy éles kagyló ... a homokban.'::text,'van'::text,'vannak'::text,'lenni'::text,'Nyilván remek hely a lábujjaknak: egy éles kagyló van a homokban.'::text),
(323409,35935,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Gäste im Flur warten auf die Toilette.'::text,'Diese'::text,'Dieser'::text,'Jener'::text,'Diese Gäste im Flur warten auf die Toilette.'::text),
(323413,35935,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... гості в коридорі чекають на туалет.'::text,'Ці'::text,'Цей'::text,'Той'::text,'Ці гості в коридорі чекають на туалет.'::text),
(323412,35935,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... invitados del pasillo esperan para ir al baño.'::text,'Estos'::text,'Este'::text,'Ese'::text,'Estos invitados del pasillo esperan para ir al baño.'::text),
(323411,35935,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... invités dans le couloir attendent les toilettes.'::text,'Ces'::text,'Cet'::text,'Cet'::text,'Ces invités dans le couloir attendent les toilettes.'::text),
(323414,35935,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... misafirler koridorda tuvaleti bekliyor.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu misafirler koridorda tuvaleti bekliyor.'::text),
(323415,35935,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a vendégek a folyosón a vécére várnak.'::text,'Ezek'::text,'Ez'::text,'Az'::text,'Ezek a vendégek a folyosón a vécére várnak.'::text),
(323418,35936,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wartet auf die Toilette, mit ... Handy in der Hand.'::text,'ihrem'::text,'seinem'::text,'seinem'::text,'Sie wartet auf die Toilette, mit ihrem Handy in der Hand.'::text),
(323422,35936,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона чекає на туалет із ... телефоном у руці.'::text,'своїм'::text,'його'::text,'його'::text,'Вона чекає на туалет із своїм телефоном у руці.'::text),
(323421,35936,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella espera para ir al baño con ... móvil en la mano.'::text,'su'::text,'su'::text,'su'::text,'Ella espera para ir al baño con su móvil en la mano.'::text),
(323420,35936,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle attend les toilettes avec ... téléphone à la main.'::text,'son'::text,'son'::text,'son'::text,'Elle attend les toilettes avec son téléphone à la main.'::text),
(323423,35936,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elinde ... telefonuyla tuvaleti bekliyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Elinde onun telefonuyla tuvaleti bekliyor.'::text),
(323424,35936,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ... a kezében vár a vécére.'::text,'telefonjával'::text,'telefonjával'::text,'telefonjával'::text,'A telefonjával a kezében vár a vécére.'::text),
(323427,35937,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ist die Toilette? Hinter der weißen Tür.'::text,'Wo'::text,'Wann'::text,'Wer'::text,'Wo ist die Toilette? Hinter der weißen Tür.'::text),
(323431,35937,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... туалет? За білими дверима.'::text,'Де'::text,'Коли'::text,'Хто'::text,'Де туалет? За білими дверима.'::text),
(323430,35937,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... está el baño? Detrás de la puerta blanca.'::text,'Dónde'::text,'Cuándo'::text,'Quién'::text,'¿Dónde está el baño? Detrás de la puerta blanca.'::text),
(323429,35937,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sont les toilettes ? Derrière la porte blanche.'::text,'Où'::text,'Quand'::text,'Qui'::text,'Où sont les toilettes ? Derrière la porte blanche.'::text),
(323432,35937,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tuvalet ...? Beyaz kapının arkasında.'::text,'nerede'::text,'ne zaman'::text,'kim'::text,'Tuvalet nerede? Beyaz kapının arkasında.'::text),
(323433,35937,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... van a vécé? A fehér ajtó mögött.'::text,'Hol'::text,'Mikor'::text,'Ki'::text,'Hol van a vécé? A fehér ajtó mögött.'::text),
(323436,35938,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Toilette ist ... kleinen Badezimmer.'::text,'im'::text,'auf dem'::text,'am'::text,'Die Toilette ist im kleinen Badezimmer.'::text),
(323440,35938,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Туалет ... маленькій ванній.'::text,'у'::text,'на'::text,'біля'::text,'Туалет у маленькій ванній.'::text),
(323439,35938,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El váter está ... el baño pequeño.'::text,'en'::text,'sobre'::text,'a'::text,'El váter está en el baño pequeño.'::text),
(323438,35938,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les toilettes sont ... la petite salle de bains.'::text,'dans'::text,'sur'::text,'à'::text,'Les toilettes sont dans la petite salle de bains.'::text),
(323441,35938,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tuvalet küçük banyonun ...'::text,'içinde'::text,'üstünde'::text,NULL::text,'Tuvalet küçük banyonun içinde.'::text),
(323442,35938,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vécé a kis ... van.'::text,'fürdőszobában'::text,'fürdőszobán'::text,'fürdőszobánál'::text,'A vécé a kis fürdőszobában van.'::text),
(323445,35939,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es sind sechs Gäste, also hat die Toilette eine Schlange von ...'::text,'sechs.'::text,'sechsten.'::text,'Sechsen.'::text,'Es sind sechs Gäste, also hat die Toilette eine Schlange von sechs.'::text),
(323449,35939,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Там шість гостей, тож у черзі в туалет ...'::text,'шість.'::text,'шостий.'::text,'шістки.'::text,'Там шість гостей, тож у черзі в туалет шість.'::text),
(323448,35939,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hay seis invitados, así que la cola del baño es de ...'::text,'seis.'::text,'sexto.'::text,'seis.'::text,'Hay seis invitados, así que la cola del baño es de seis.'::text),
(323447,35939,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il y a six invités, donc la queue pour les toilettes est de ...'::text,'six.'::text,'sixième.'::text,'six.'::text,'Il y a six invités, donc la queue pour les toilettes est de six.'::text),
(323450,35939,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Altı misafir var, bu yüzden tuvalet kuyruğundaki kişi sayısı ...'::text,'altı.'::text,'altıncı.'::text,'altılar.'::text,'Altı misafir var, bu yüzden tuvalet kuyruğundaki kişi sayısı altı.'::text),
(323451,35939,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hat vendég van, úgyhogy a vécé előtt álló sor hossza ...'::text,'hat.'::text,'hatodik.'::text,'hatosok.'::text,'Hat vendég van, úgyhogy a vécé előtt álló sor hossza hat.'::text),
(323454,35940,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern Abend ... du so höflich an die Toilettentür. Respekt.'::text,'klopftest'::text,'klopfst'::text,'klopft'::text,'Gestern Abend klopftest du so höflich an die Toilettentür. Respekt.'::text),
(323458,35940,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора ввечері ти так чемно ... у двері туалету. Респект.'::text,'постукала'::text,'стукаєш'::text,'стукає'::text,'Учора ввечері ти так чемно постукала у двері туалету. Респект.'::text),
(323457,35940,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anoche ... a la puerta del baño con mucha educación. Respeto.'::text,'llamaste'::text,'llamas'::text,'llama'::text,'Anoche llamaste a la puerta del baño con mucha educación. Respeto.'::text),
(323456,35940,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier soir, tu ... à la porte des toilettes si poliment. Respect.'::text,'as frappé'::text,'frappes'::text,'frappe'::text,'Hier soir, tu as frappé à la porte des toilettes si poliment. Respect.'::text),
(323459,35940,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün gece tuvalet kapısını çok kibarca ... Saygı.'::text,'çaldın'::text,'çalarsın'::text,'çalar'::text,'Dün gece tuvalet kapısını çok kibarca çaldın Saygı.'::text),
(323460,35940,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap este olyan udvariasan ... a vécéajtón. Respekt.'::text,'kopogtál'::text,'kopogsz'::text,'kopog'::text,'Tegnap este olyan udvariasan kopogtál a vécéajtón. Respekt.'::text),
(302304,33590,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Stuhl wackelt, also ... sie ihren Werkzeugkoffer öffnen.'::text,'wird'::text,'wird'::text,'wird'::text,'Der Stuhl wackelt, also wird sie ihren Werkzeugkoffer öffnen.'::text),
(302308,33590,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стілець хитається, тож вона ... відкрити свій набір інструментів.'::text,'збирається'::text,'збирається'::text,'збирається'::text,'Стілець хитається, тож вона збирається відкрити свій набір інструментів.'::text),
(302307,33590,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La silla cojea, así que ella ... abrir su caja de herramientas.'::text,'va a'::text,'va a'::text,'va a'::text,'La silla cojea, así que ella va a abrir su caja de herramientas.'::text),
(302306,33590,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La chaise est bancale, alors elle ... ouvrir sa boîte à outils.'::text,'va'::text,'va'::text,'va'::text,'La chaise est bancale, alors elle va ouvrir sa boîte à outils.'::text),
(302309,33590,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sandalye sallanıyor, bu yüzden alet çantasını ...'::text,'açacak'::text,'açacak'::text,'açacak'::text,'Sandalye sallanıyor, bu yüzden alet çantasını açacak.'::text),
(302310,33590,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Billeg a szék, úgyhogy ki ... nyitni a szerszámkészletét.'::text,'fogja'::text,'fogja'::text,'fogja'::text,'Billeg a szék, úgyhogy ki fogja nyitni a szerszámkészletét.'::text),
(302313,33591,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schraubenzieher in der Hand, ... sie natürlich den ganzen Koffer benutzen.'::text,'wird'::text,'wird'::text,NULL::text,'Schraubenzieher in der Hand, wird sie natürlich den ganzen Koffer benutzen.'::text),
(302317,33591,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'З викруткою в руці вона, звісно, ... використовувати весь набір.'::text,'збирається'::text,'буде'::text,NULL::text,'З викруткою в руці вона, звісно, збирається використовувати весь набір.'::text),
(302316,33591,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Destornillador en mano, ... usar todo el kit, obviamente.'::text,'va a'::text,NULL::text,NULL::text,'Destornillador en mano, va a usar todo el kit, obviamente.'::text),
(302315,33591,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tournevis en main, elle ... utiliser toute la boîte, évidemment.'::text,'va'::text,NULL::text,NULL::text,'Tournevis en main, elle va utiliser toute la boîte, évidemment.'::text),
(302318,33591,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elinde tornavida, tabii ki bütün seti ...'::text,'kullanacak'::text,'kullanacak'::text,NULL::text,'Elinde tornavida, tabii ki bütün seti kullanacak.'::text),
(302319,33591,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csavarhúzóval a kezében nyilván az egész készletet használni ...'::text,'fogja'::text,'fogja'::text,NULL::text,'Csavarhúzóval a kezében nyilván az egész készletet használni fogja.'::text),
(302331,33593,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es bleibt nicht ... Zeit! Mach den Koffer auf, bevor der Stuhl zusammenbricht!'::text,'viel'::text,'viele'::text,'eine'::text,'Es bleibt nicht viel Zeit! Mach den Koffer auf, bevor der Stuhl zusammenbricht!'::text),
(302335,33593,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Немає ... часу! Відкривай набір, поки стілець не розвалився!'::text,'багато'::text,'багато'::text,NULL::text,'Немає багато часу! Відкривай набір, поки стілець не розвалився!'::text),
(302334,33593,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No hay ... tiempo! ¡Abre el kit antes de que la silla se derrumbe!'::text,'mucho'::text,'muchos'::text,'un'::text,'¡No hay mucho tiempo! ¡Abre el kit antes de que la silla se derrumbe!'::text),
(302333,33593,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il n''y a pas ... temps ! Ouvre la boîte avant que la chaise s''effondre !'::text,'beaucoup de'::text,'beaucoup de'::text,'un'::text,'Il n''y a pas beaucoup de temps ! Ouvre la boîte avant que la chaise s''effondre !'::text),
(302336,33593,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... zaman yok! Sandalye çökmeden seti aç!'::text,'Çok'::text,'Çok'::text,'Bir'::text,'Çok zaman yok! Sandalye çökmeden seti aç!'::text),
(302337,33593,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nincs ... idő! Nyisd ki a készletet, mielőtt összeomlik a szék!'::text,'sok'::text,'sok'::text,'egy'::text,'Nincs sok idő! Nyisd ki a készletet, mielőtt összeomlik a szék!'::text),
(302340,33594,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Da ... fünfzig Werkzeuge im Koffer! Stuhl, du bist erledigt!'::text,'sind'::text,'ist'::text,'sein'::text,'Da sind fünfzig Werkzeuge im Koffer! Stuhl, du bist erledigt!'::text),
(302344,33594,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У наборі ... п''ятдесят інструментів! Стільце, тобі кінець!'::text,'є'::text,'є'::text,'бути'::text,'У наборі є п''ятдесят інструментів! Стільце, тобі кінець!'::text),
(302343,33594,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... cincuenta herramientas en el kit! ¡Silla, estás perdida!'::text,'Hay'::text,'Hay'::text,'Hay'::text,'¡Hay cincuenta herramientas en el kit! ¡Silla, estás perdida!'::text),
(302342,33594,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... cinquante outils dans la boîte ! Chaise, tu es fichue !'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a cinquante outils dans la boîte ! Chaise, tu es fichue !'::text),
(302345,33594,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sette elli alet ...! Sandalye, işin bitti!'::text,'var'::text,'var'::text,'olmak'::text,'Sette elli alet var! Sandalye, işin bitti!'::text),
(302346,33594,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ötven szerszám ... a készletben! Szék, neked annyi!'::text,'van'::text,'van'::text,'lenni'::text,'Ötven szerszám van a készletben! Szék, neked annyi!'::text),
(302349,33595,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, anscheinend sagt ihr Vermieter, dass sie den Stuhl mit ihrem Koffer reparieren ...'::text,'muss'::text,'muss'::text,'sollte'::text,'Hör mal, anscheinend sagt ihr Vermieter, dass sie den Stuhl mit ihrem Koffer reparieren muss.'::text),
(302353,33595,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, здається, її орендодавець каже, що вона ... полагодити стілець своїм набором.'::text,'має'::text,'мусить'::text,'мала б'::text,'Слухай, здається, її орендодавець каже, що вона має полагодити стілець своїм набором.'::text),
(302352,33595,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, parece que su casero dice que ella ... arreglar la silla con su kit.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Oye, parece que su casero dice que ella tiene que arreglar la silla con su kit.'::text),
(302351,33595,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment son propriétaire dit qu''elle ... réparer la chaise avec sa boîte à outils.'::text,'doit'::text,'doit'::text,'devrait'::text,'Écoute, apparemment son propriétaire dit qu''elle doit réparer la chaise avec sa boîte à outils.'::text),
(302354,33595,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, güya ev sahibi diyor ki sandalyeyi kendi setiyle ...'::text,'tamir etmek zorunda'::text,'tamir etmeli'::text,'tamir etmeli'::text,'Dinle, güya ev sahibi diyor ki sandalyeyi kendi setiyle tamir etmek zorunda.'::text),
(302355,33595,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag a főbérlője azt mondja, hogy a készletével ... megjavítania a széket.'::text,'kell'::text,'kell'::text,'kellene'::text,'Figyelj, állítólag a főbérlője azt mondja, hogy a készletével kell megjavítania a széket.'::text),
(302358,33596,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, ich hab gehört, jeder ... sich so einen Koffer wie ihren kaufen.'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Mädel, ich hab gehört, jeder sollte sich so einen Koffer wie ihren kaufen.'::text),
(302362,33596,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що кожен ... купити такий набір, як у неї.'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Подруго, я чула, що кожен мав би купити такий набір, як у неї.'::text),
(302361,33596,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, he oído que todo el mundo ... comprarse un kit como el suyo.'::text,'debería'::text,'debería'::text,'debería'::text,'Tía, he oído que todo el mundo debería comprarse un kit como el suyo.'::text),
(302360,33596,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, il paraît que tout le monde ... acheter une boîte comme la sienne.'::text,'devrait'::text,'devrait'::text,'devrait'::text,'Meuf, il paraît que tout le monde devrait acheter une boîte comme la sienne.'::text),
(302363,33596,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duydum ki herkes onunki gibi bir set ...'::text,'almalı'::text,'almalı'::text,'almalı'::text,'Kızım, duydum ki herkes onunki gibi bir set almalı.'::text),
(302364,33596,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy mindenkinek ... vennie egy ilyen készletet, mint az övé.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Csajszi, azt hallottam, hogy mindenkinek kellene vennie egy ilyen készletet, mint az övé.'::text),
(323481,35943,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schau, der Zahnarzt ... ihre Vorderzähne mit einem kleinen Spiegel.'::text,'untersucht'::text,'untersucht'::text,'untersucht'::text,'Schau, der Zahnarzt untersucht ihre Vorderzähne mit einem kleinen Spiegel.'::text),
(323485,35943,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дивись, стоматолог ... її передні зуби маленьким дзеркальцем.'::text,'оглядає'::text,'оглядає'::text,'оглядає'::text,'Дивись, стоматолог оглядає її передні зуби маленьким дзеркальцем.'::text),
(323484,35943,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mira, el dentista ... sus dientes delanteros con un espejito.'::text,'está revisando'::text,'revisa'::text,'está revisando'::text,'Mira, el dentista está revisando sus dientes delanteros con un espejito.'::text),
(323483,35943,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Regarde, le dentiste ... ses dents de devant avec un petit miroir.'::text,'est en train d''examiner'::text,'examine'::text,'est en train d''examiner'::text,'Regarde, le dentiste est en train d''examiner ses dents de devant avec un petit miroir.'::text),
(323486,35943,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bak, dişçi onun ön dişlerini küçük bir aynayla ...'::text,'kontrol ediyor'::text,'kontrol eder'::text,'kontrol ediyor'::text,'Bak, dişçi onun ön dişlerini küçük bir aynayla kontrol ediyor.'::text),
(323487,35943,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nézd, a fogorvos egy kis tükörrel ... az első fogait.'::text,'vizsgálja'::text,'vizsgálja'::text,'vizsgálja'::text,'Nézd, a fogorvos egy kis tükörrel vizsgálja az első fogait.'::text),
(323490,35944,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal: Ich hab gehört, sie hasst Zahnärzte, aber heute ... einer ihre Zähne.'::text,'untersucht'::text,'untersucht'::text,NULL::text,'Rate mal: Ich hab gehört, sie hasst Zahnärzte, aber heute untersucht einer ihre Zähne.'::text),
(323494,35944,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви: я чула, що вона ненавидить стоматологів, але сьогодні один ... їй зуби.'::text,'оглядає'::text,'оглядає'::text,NULL::text,'Уяви: я чула, що вона ненавидить стоматологів, але сьогодні один оглядає їй зуби.'::text),
(323493,35944,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina: he oído que odia a los dentistas, pero hoy uno le ... los dientes.'::text,'está revisando'::text,'revisa'::text,NULL::text,'Adivina: he oído que odia a los dentistas, pero hoy uno le está revisando los dientes.'::text),
(323492,35944,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi : il paraît qu''elle déteste les dentistes, mais aujourd''hui, il y en a un qui ... ses dents.'::text,'est en train d''examiner'::text,'examine'::text,NULL::text,'Devine quoi : il paraît qu''elle déteste les dentistes, mais aujourd''hui, il y en a un qui est en train d''examiner ses dents.'::text),
(323495,35944,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım: duyduğuma göre dişçilerden nefret ediyormuş ama bugün biri dişlerini ...'::text,'kontrol ediyor'::text,'kontrol eder'::text,NULL::text,'Bil bakalım: duyduğuma göre dişçilerden nefret ediyormuş ama bugün biri dişlerini kontrol ediyor.'::text),
(323496,35944,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld: azt hallottam, hogy utálja a fogorvosokat, de ma az egyik ... a fogait.'::text,'vizsgálja'::text,'vizsgálja'::text,NULL::text,'Képzeld: azt hallottam, hogy utálja a fogorvosokat, de ma az egyik vizsgálja a fogait.'::text),
(323499,35945,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, du bist so ruhig auf diesem Stuhl. Als Nächstes ... deine Zähne in diesen Apfel beißen.'::text,'werden'::text,'beißt'::text,'bissen'::text,'Respekt, du bist so ruhig auf diesem Stuhl. Als Nächstes werden deine Zähne in diesen Apfel beißen.'::text),
(323503,35945,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Респект, ти така спокійна в тому кріслі. Далі твої зуби ... те яблуко.'::text,'вкусять'::text,'кусає'::text,'вкусили'::text,'Респект, ти така спокійна в тому кріслі. Далі твої зуби вкусять те яблуко.'::text),
(323502,35945,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respeto, estás muy tranquila en esa silla. Después, tus dientes ... esa manzana.'::text,'morderán'::text,'muerde'::text,'mordieron'::text,'Respeto, estás muy tranquila en esa silla. Después, tus dientes morderán esa manzana.'::text),
(323501,35945,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respect, tu es trop calme dans ce fauteuil. Ensuite, tes dents ... dans cette pomme.'::text,'croqueront'::text,'croque'::text,'ont croqué'::text,'Respect, tu es trop calme dans ce fauteuil. Ensuite, tes dents croqueront dans cette pomme.'::text),
(323504,35945,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saygı, o koltukta çok sakinsin. Sırada dişlerin o elmayı ...'::text,'ısıracak'::text,'ısırır'::text,'ısırdı'::text,'Saygı, o koltukta çok sakinsin. Sırada dişlerin o elmayı ısıracak.'::text),
(323505,35945,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Respekt, olyan nyugodt vagy abban a székben. Ezután a fogaid ... abba az almába.'::text,'bele fognak harapni'::text,'beleharap'::text,'beleharaptak'::text,'Respekt, olyan nyugodt vagy abban a székben. Ezután a fogaid bele fognak harapni abba az almába.'::text),
(323508,35946,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kluger Plan, ehrlich: Du ... gleich nach der Zahnkontrolle in diesen Apfel beißen.'::text,'wirst'::text,'wird'::text,'wirst'::text,'Kluger Plan, ehrlich: Du wirst gleich nach der Zahnkontrolle in diesen Apfel beißen.'::text),
(323512,35946,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Розумний план, чесно: ти ... те яблуко одразу після огляду зубів.'::text,'збираєшся вкусити'::text,'збирається вкусити'::text,'збираєшся вкусити'::text,'Розумний план, чесно: ти збираєшся вкусити те яблуко одразу після огляду зубів.'::text),
(323511,35946,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plan inteligente, la verdad: ... esa manzana justo después de la revisión de dientes.'::text,'vas a morder'::text,'va a morder'::text,'vas a morder'::text,'Plan inteligente, la verdad: vas a morder esa manzana justo después de la revisión de dientes.'::text),
(323510,35946,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plan malin, franchement : tu ... dans cette pomme juste après ton contrôle dentaire.'::text,'vas croquer'::text,'va croquer'::text,'vas croquer'::text,'Plan malin, franchement : tu vas croquer dans cette pomme juste après ton contrôle dentaire.'::text),
(323513,35946,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akıllıca plan, cidden: diş kontrolünden hemen sonra o elmayı ...'::text,'ısıracaksın'::text,'ısıracak'::text,'ısıracaksın'::text,'Akıllıca plan, cidden: diş kontrolünden hemen sonra o elmayı ısıracaksın.'::text),
(323514,35946,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okos terv, komolyan: a fogvizsgálat után rögtön ... abba az almába.'::text,'bele fogsz harapni'::text,'bele fog harapni'::text,'bele fogsz harapni'::text,'Okos terv, komolyan: a fogvizsgálat után rögtön bele fogsz harapni abba az almába.'::text),
(323517,35947,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super gemacht, klar: Der Apfel berührt ihre Zähne. Sie ... reinbeißen.'::text,'wird'::text,'wird'::text,NULL::text,'Super gemacht, klar: Der Apfel berührt ihre Zähne. Sie wird reinbeißen.'::text),
(323521,35947,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота, звісно: яблуко торкається її зубів. Вона ... його кусати.'::text,'збирається'::text,'буде'::text,NULL::text,'Чудова робота, звісно: яблуко торкається її зубів. Вона збирається його кусати.'::text),
(323520,35947,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen trabajo, claro: la manzana toca sus dientes. Ella ... morderla.'::text,'va a'::text,NULL::text,NULL::text,'Buen trabajo, claro: la manzana toca sus dientes. Ella va a morderla.'::text),
(323519,35947,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bravo, évidemment : la pomme touche ses dents. Elle ... la croquer.'::text,'va'::text,NULL::text,NULL::text,'Bravo, évidemment : la pomme touche ses dents. Elle va la croquer.'::text),
(323522,35947,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika iş, tabii: elma dişlerine değiyor. Onu ...'::text,'ısıracak'::text,'ısıracak'::text,NULL::text,'Harika iş, tabii: elma dişlerine değiyor. Onu ısıracak.'::text),
(323523,35947,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka, persze: az alma hozzáér a fogaihoz. Bele ... harapni.'::text,'fog'::text,'fog'::text,NULL::text,'Szép munka, persze: az alma hozzáér a fogaihoz. Bele fog harapni.'::text),
(323535,35949,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie hat ... schlechten Zähne, der Zahnarzt sagt, alles gut.'::text,'keine'::text,'einige'::text,'viel'::text,'Alter, sie hat keine schlechten Zähne, der Zahnarzt sagt, alles gut.'::text),
(323539,35949,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, у неї нема ... поганих зубів, стоматолог каже, що все норм.'::text,'жодних'::text,'якихось'::text,'багато'::text,'Бро, у неї нема жодних поганих зубів, стоматолог каже, що все норм.'::text),
(323538,35949,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, no tiene ... diente malo, el dentista dice que todo bien.'::text,'ningún'::text,'algunos'::text,'mucho'::text,'Tío, no tiene ningún diente malo, el dentista dice que todo bien.'::text),
(323537,35949,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, elle n''a ... mauvaise dent, le dentiste dit que tout va bien.'::text,'aucune'::text,'des'::text,'beaucoup de'::text,'Mec, elle n''a aucune mauvaise dent, le dentiste dit que tout va bien.'::text),
(323540,35949,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onun ... çürük dişi yok, dişçi her şey yolunda diyor.'::text,'hiç'::text,'bazı'::text,'çok'::text,'Kanka, onun hiç çürük dişi yok, dişçi her şey yolunda diyor.'::text),
(323541,35949,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, neki ... rossz foga sincs, a fogorvos szerint minden oké.'::text,'semmilyen'::text,'néhány'::text,'sok'::text,'Tesó, neki semmilyen rossz foga sincs, a fogorvos szerint minden oké.'::text),
(323544,35950,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In ihrem breiten Lächeln ... zwei weiße Vorderzähne.'::text,'sind'::text,'ist'::text,'sein'::text,'In ihrem breiten Lächeln sind zwei weiße Vorderzähne.'::text),
(323548,35950,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У її широкій усмішці ... два білі передні зуби.'::text,'є'::text,'є'::text,'бути'::text,'У її широкій усмішці є два білі передні зуби.'::text),
(323547,35950,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En su gran sonrisa ... dos dientes delanteros blancos.'::text,'hay'::text,'hay'::text,'hay'::text,'En su gran sonrisa hay dos dientes delanteros blancos.'::text),
(323546,35950,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans son grand sourire, ... deux dents de devant blanches.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Dans son grand sourire, il y a deux dents de devant blanches.'::text),
(323549,35950,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kocaman gülümsemesinde iki beyaz ön diş ...'::text,'var'::text,'var'::text,'olmak'::text,'Kocaman gülümsemesinde iki beyaz ön diş var.'::text),
(323550,35950,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagy mosolyában két fehér első fog ...'::text,'van'::text,'van'::text,'lenni'::text,'A nagy mosolyában két fehér első fog van.'::text),
(323562,35952,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Schlimmste! Er ... eine Zahnbürste, aber keinen Kamm!'::text,'hat'::text,'haben'::text,'hat'::text,'Das Schlimmste! Er hat eine Zahnbürste, aber keinen Kamm!'::text),
(323566,35952,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Найгірше! Він ... зубну щітку, але не має гребінця!'::text,'має'::text,'мати'::text,'має'::text,'Найгірше! Він має зубну щітку, але не має гребінця!'::text),
(323565,35952,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Lo peor! ¡Él ... cepillo de dientes, pero no peine!'::text,'tiene'::text,'tienen'::text,'tiene'::text,'¡Lo peor! ¡Él tiene cepillo de dientes, pero no peine!'::text),
(323564,35952,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pire ! Il ... une brosse à dents, mais pas de peigne !'::text,'a'::text,'ont'::text,'a'::text,'Le pire ! Il a une brosse à dents, mais pas de peigne !'::text),
(323567,35952,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En kötüsü! Onun bir diş fırçası ... ama tarağı yok!'::text,'var'::text,'var'::text,'var'::text,'En kötüsü! Onun bir diş fırçası var ama tarağı yok!'::text),
(323568,35952,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A legrosszabb! Neki ... fogkeféje, de fésűje nincs!'::text,'van'::text,'van'::text,'van'::text,'A legrosszabb! Neki van fogkeféje, de fésűje nincs!'::text),
(323571,35953,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nie wieder! Er ... seine Zahnbürste jeden Abend in diesen Becher!'::text,'stellt'::text,'stellen'::text,'stellend'::text,'Nie wieder! Er stellt seine Zahnbürste jeden Abend in diesen Becher!'::text),
(323575,35953,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи більше! Він щовечора ... свою зубну щітку в ту склянку!'::text,'ставить'::text,'ставити'::text,'ставлячи'::text,'Ніколи більше! Він щовечора ставить свою зубну щітку в ту склянку!'::text),
(323574,35953,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nunca más! ¡Él ... su cepillo de dientes en ese vaso todas las noches!'::text,'pone'::text,'poner'::text,'poniendo'::text,'¡Nunca más! ¡Él pone su cepillo de dientes en ese vaso todas las noches!'::text),
(323573,35953,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plus jamais ! Il ... sa brosse à dents dans ce verre tous les soirs !'::text,'met'::text,'mettre'::text,'mettant'::text,'Plus jamais ! Il met sa brosse à dents dans ce verre tous les soirs !'::text),
(323576,35953,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir daha asla! Her gece diş fırçasını o bardağa ...!'::text,'koyar'::text,'koymak'::text,'koyarak'::text,'Bir daha asla! Her gece diş fırçasını o bardağa koyar!'::text),
(323577,35953,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha többé! Minden este abba a pohárba ... a fogkeféjét!'::text,'teszi'::text,'tenni'::text,'tevő'::text,'Soha többé! Minden este abba a pohárba teszi a fogkeféjét!'::text),
(323589,35955,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im weißen Becher ist Platz für zwei ...'::text,'Zahnbürsten.'::text,'Zahnbürste.'::text,'Zahnbürsten.'::text,'Im weißen Becher ist Platz für zwei Zahnbürsten.'::text),
(323593,35955,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У білій склянці є місце для двох ...'::text,'зубних щіток.'::text,'зубної щітки.'::text,'зубних щіток.'::text,'У білій склянці є місце для двох зубних щіток.'::text),
(323592,35955,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En el vaso blanco caben dos ...'::text,'cepillos de dientes.'::text,'cepillo de dientes.'::text,'cepillos de dientes.'::text,'En el vaso blanco caben dos cepillos de dientes.'::text),
(323591,35955,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le verre blanc a de la place pour deux ...'::text,'brosses à dents.'::text,'brosse à dents.'::text,'brosses à dents.'::text,'Le verre blanc a de la place pour deux brosses à dents.'::text),
(323594,35955,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beyaz bardakta iki ... için yer var.'::text,'diş fırçası'::text,'diş fırçası'::text,'diş fırçası'::text,'Beyaz bardakta iki diş fırçası için yer var.'::text),
(323595,35955,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fehér pohárban elfér két ...'::text,'fogkefe.'::text,'fogkefe.'::text,'fogkefe.'::text,'A fehér pohárban elfér két fogkefe.'::text),
(323598,35956,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, das ist keine Haarbürste, Digga, das ist ... Zahnbürste.'::text,'eine'::text,'eine'::text,'die'::text,'Ey, das ist keine Haarbürste, Digga, das ist eine Zahnbürste.'::text),
(323602,35956,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, це не щітка для волосся, бро, це ... зубна щітка.'::text,''::text,NULL::text,NULL::text,'Йо, це не щітка для волосся, бро, це зубна щітка.'::text),
(323601,35956,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, eso no es un cepillo del pelo, tío, es ... cepillo de dientes.'::text,'un'::text,'un'::text,'el'::text,'Oye, eso no es un cepillo del pelo, tío, es un cepillo de dientes.'::text),
(323600,35956,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, c''est pas une brosse à cheveux, frère, c''est ... brosse à dents.'::text,'une'::text,'une'::text,'la'::text,'Wesh, c''est pas une brosse à cheveux, frère, c''est une brosse à dents.'::text),
(323603,35956,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o saç fırçası değil, dostum, o ... diş fırçası.'::text,'bir'::text,'bir'::text,NULL::text,'Kanka, o saç fırçası değil, dostum, o bir diş fırçası.'::text),
(323604,35956,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, az nem hajkefe, tesó, az ... fogkefe.'::text,'egy'::text,'egy'::text,'a'::text,'Figyu, az nem hajkefe, tesó, az egy fogkefe.'::text),
(323616,35958,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Zahnbürste ist alt, also ... er eine neue kaufen.'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Seine Zahnbürste ist alt, also sollte er eine neue kaufen.'::text),
(323620,35958,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його зубна щітка стара, тож він ... купити нову.'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Його зубна щітка стара, тож він мав би купити нову.'::text),
(323619,35958,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su cepillo de dientes está viejo, así que él ... comprar uno nuevo.'::text,'debería'::text,'debería'::text,'debería'::text,'Su cepillo de dientes está viejo, así que él debería comprar uno nuevo.'::text),
(323618,35958,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa brosse à dents est vieille, donc il ... en acheter une nouvelle.'::text,'devrait'::text,'devrait'::text,'devrait'::text,'Sa brosse à dents est vieille, donc il devrait en acheter une nouvelle.'::text),
(323621,35958,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diş fırçası eski, bu yüzden yenisini ...'::text,'almalı'::text,'almalı'::text,'almalı'::text,'Diş fırçası eski, bu yüzden yenisini almalı.'::text),
(323622,35958,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Régi a fogkeféje, ezért ... vennie egy újat.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Régi a fogkeféje, ezért kellene vennie egy újat.'::text),
(323625,35959,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er lächelt in den Spiegel, ... seine Zahnbürste gute Arbeit geleistet hat.'::text,'weil'::text,'aber'::text,'also'::text,'Er lächelt in den Spiegel, weil seine Zahnbürste gute Arbeit geleistet hat.'::text),
(323629,35959,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він усміхається в дзеркало, ... його зубна щітка добре попрацювала.'::text,'бо'::text,'але'::text,'тому'::text,'Він усміхається в дзеркало, бо його зубна щітка добре попрацювала.'::text),
(323628,35959,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonríe al espejo ... su cepillo de dientes ha hecho un buen trabajo.'::text,'porque'::text,'pero'::text,'así que'::text,'Sonríe al espejo porque su cepillo de dientes ha hecho un buen trabajo.'::text),
(323627,35959,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il sourit au miroir ... sa brosse à dents a fait du bon travail.'::text,'parce que'::text,'mais'::text,'donc'::text,'Il sourit au miroir parce que sa brosse à dents a fait du bon travail.'::text),
(323630,35959,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aynaya gülümsüyor ... diş fırçası iyi iş çıkardı.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Aynaya gülümsüyor çünkü diş fırçası iyi iş çıkardı.'::text),
(323631,35959,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mosolyog a tükörbe, ... a fogkeféje jó munkát végzett.'::text,'mert'::text,'de'::text,'ezért'::text,'Mosolyog a tükörbe, mert a fogkeféje jó munkát végzett.'::text),
(312069,34675,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... hält er an? Die Ampel ist rot.'::text,'Warum'::text,'Wo'::text,'Wer'::text,'Warum hält er an? Die Ampel ist rot.'::text),
(312073,34675,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... він зупиняється? Світлофор червоний.'::text,'Чому'::text,'Де'::text,'Хто'::text,'Чому він зупиняється? Світлофор червоний.'::text),
(312072,34675,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... se para? El semáforo está en rojo.'::text,'Por qué'::text,'Dónde'::text,'Quién'::text,'¿Por qué se para? El semáforo está en rojo.'::text),
(312071,34675,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... s''arrête-t-il ? Le feu est rouge.'::text,'Pourquoi'::text,'Où'::text,'Qui'::text,'Pourquoi s''arrête-t-il ? Le feu est rouge.'::text),
(312074,34675,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... duruyor? Işık kırmızı.'::text,'Neden'::text,'Nerede'::text,'Kim'::text,'Neden duruyor? Işık kırmızı.'::text),
(312075,34675,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... áll meg? A lámpa piros.'::text,'Miért'::text,'Hol'::text,'Ki'::text,'Miért áll meg? A lámpa piros.'::text),
(312078,34676,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Ampel ... auf Rot, also hielt der Fahrer an.'::text,'sprang'::text,'springt'::text,'springen'::text,'Die Ampel sprang auf Rot, also hielt der Fahrer an.'::text),
(312082,34676,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Світлофор ... на червоний, тож кур''єр зупинився.'::text,'перемкнувся'::text,'перемикається'::text,'перемикатися'::text,'Світлофор перемкнувся на червоний, тож кур''єр зупинився.'::text),
(312081,34676,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El semáforo ... rojo, así que el repartidor paró.'::text,'se puso'::text,'se pone'::text,'ponerse'::text,'El semáforo se puso rojo, así que el repartidor paró.'::text),
(312080,34676,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le feu ... au rouge, alors le livreur s''est arrêté.'::text,'est passé'::text,'passe'::text,'passer'::text,'Le feu est passé au rouge, alors le livreur s''est arrêté.'::text),
(312083,34676,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Işık kırmızıya ..., bu yüzden kurye durdu.'::text,'döndü'::text,'döner'::text,'dönmek'::text,'Işık kırmızıya döndü, bu yüzden kurye durdu.'::text),
(312084,34676,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lámpa pirosra ..., ezért a futár megállt.'::text,'váltott'::text,'vált'::text,'váltani'::text,'A lámpa pirosra váltott, ezért a futár megállt.'::text),
(312087,34677,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, Alter, diese Ampel ist normalerweise grün, aber gestern ... sie zweimal auf Rot.'::text,'sprang'::text,'springt'::text,NULL::text,'Nee, Alter, diese Ampel ist normalerweise grün, aber gestern sprang sie zweimal auf Rot.'::text),
(312091,34677,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, бро, цей світлофор зазвичай зелений, але вчора він двічі ... на червоний.'::text,'перемкнувся'::text,'перемикається'::text,NULL::text,'Не, бро, цей світлофор зазвичай зелений, але вчора він двічі перемкнувся на червоний.'::text),
(312090,34677,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, este semáforo suele estar en verde, pero ayer ... en rojo dos veces.'::text,'se puso'::text,'se pone'::text,NULL::text,'Qué va, tío, este semáforo suele estar en verde, pero ayer se puso en rojo dos veces.'::text),
(312089,34677,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, mec, ce feu est d''habitude vert, mais hier il ... au rouge deux fois.'::text,'est passé'::text,'passe'::text,NULL::text,'Nan, mec, ce feu est d''habitude vert, mais hier il est passé au rouge deux fois.'::text),
(312092,34677,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, bu ışık genelde yeşildir ama dün iki kez kırmızıya ...'::text,'döndü'::text,'döner'::text,NULL::text,'Yok kanka, bu ışık genelde yeşildir ama dün iki kez kırmızıya döndü.'::text),
(312093,34677,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, tesó, ez a lámpa általában zöld, de tegnap kétszer is pirosra ...'::text,'váltott'::text,'vált'::text,NULL::text,'Á, tesó, ez a lámpa általában zöld, de tegnap kétszer is pirosra váltott.'::text),
(312096,34678,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deadline in 5 Minuten, aber der Fahrer ... jetzt an einer roten Ampel.'::text,'wartet'::text,'wartet'::text,'wartet'::text,'Deadline in 5 Minuten, aber der Fahrer wartet jetzt an einer roten Ampel.'::text),
(312100,34678,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дедлайн через 5 хвилин, а кур''єр зараз ... на червоному світлі.'::text,'чекає'::text,'чекає'::text,'чекає'::text,'Дедлайн через 5 хвилин, а кур''єр зараз чекає на червоному світлі.'::text),
(312099,34678,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fecha límite en 5 minutos, pero el repartidor ... en un semáforo en rojo ahora.'::text,'está esperando'::text,'espera'::text,'está esperando'::text,'Fecha límite en 5 minutos, pero el repartidor está esperando en un semáforo en rojo ahora.'::text),
(312098,34678,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deadline dans 5 minutes, mais le livreur ... à un feu rouge maintenant.'::text,'est en train d''attendre'::text,'attend'::text,'est en train d''attendre'::text,'Deadline dans 5 minutes, mais le livreur est en train d''attendre à un feu rouge maintenant.'::text),
(312101,34678,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teslim tarihine 5 dakika var ama kurye şu an kırmızı ışıkta ...'::text,'bekliyor'::text,'bekler'::text,'bekliyor'::text,'Teslim tarihine 5 dakika var ama kurye şu an kırmızı ışıkta bekliyor.'::text),
(312102,34678,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'5 perc a határidőig, de a futár most egy piros lámpánál ...'::text,'vár'::text,'vár'::text,'vár'::text,'5 perc a határidőig, de a futár most egy piros lámpánál vár.'::text),
(312114,34680,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du bist ... als alle an dieser roten Ampel.'::text,'geduldiger'::text,'geduldiger'::text,'am geduldigsten'::text,'Ehrlich, du bist geduldiger als alle an dieser roten Ampel.'::text),
(312118,34680,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... за всіх на цьому червоному світлі.'::text,'більш терпляча'::text,'терплячіша'::text,'найтерплячіша'::text,'Чесно, ти більш терпляча за всіх на цьому червоному світлі.'::text),
(312117,34680,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De verdad, eres ... que todos en este semáforo en rojo.'::text,'más paciente'::text,'más paciente'::text,'la más paciente'::text,'De verdad, eres más paciente que todos en este semáforo en rojo.'::text),
(312116,34680,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu es ... que tout le monde à ce feu rouge.'::text,'plus patiente'::text,'plus patiente'::text,'la plus patiente'::text,'Franchement, tu es plus patiente que tout le monde à ce feu rouge.'::text),
(312119,34680,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cidden, bu kırmızı ışıktaki herkesten ...'::text,'daha sabırlısın'::text,'daha sabırlısın'::text,'en sabırlısın'::text,'Cidden, bu kırmızı ışıktaki herkesten daha sabırlısın.'::text),
(312120,34680,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ... vagy mindenkinél ennél a piros lámpánál.'::text,'türelmesebb'::text,'türelmesebb'::text,'legtürelmesebb'::text,'Őszintén, türelmesebb vagy mindenkinél ennél a piros lámpánál.'::text),
(312123,34681,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ziemlich beeindruckend: Du wartest so ... an der roten Ampel.'::text,'ruhig'::text,'ruhig'::text,'Ruhe'::text,'Ziemlich beeindruckend: Du wartest so ruhig an der roten Ampel.'::text),
(312127,34681,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Досить вражає: ти так ... чекаєш на червоному.'::text,'спокійно'::text,'спокійний'::text,'спокій'::text,'Досить вражає: ти так спокійно чекаєш на червоному.'::text),
(312126,34681,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bastante impresionante: esperas tan ... en el semáforo en rojo.'::text,'tranquilamente'::text,'tranquilo'::text,'tranquilidad'::text,'Bastante impresionante: esperas tan tranquilamente en el semáforo en rojo.'::text),
(312125,34681,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Plutôt impressionnant : tu attends si ... au feu rouge.'::text,'calmement'::text,'calme'::text,'calme'::text,'Plutôt impressionnant : tu attends si calmement au feu rouge.'::text),
(312128,34681,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Epey etkileyici: kırmızı ışıkta öyle ... bekliyorsun.'::text,'sakince'::text,'sakin'::text,'sakinlik'::text,'Epey etkileyici: kırmızı ışıkta öyle sakince bekliyorsun.'::text),
(312129,34681,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elég lenyűgöző: olyan ... vársz a piros lámpánál.'::text,'nyugodtan'::text,'nyugodt'::text,'nyugalom'::text,'Elég lenyűgöző: olyan nyugodtan vársz a piros lámpánál.'::text),
(324876,36098,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ihnen mit geschlossenen Augen! Völlig verrückt!'::text,'vertraut'::text,'vertrauen'::text,'vertrauend'::text,'Sie vertraut ihnen mit geschlossenen Augen! Völlig verrückt!'::text),
(324880,36098,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... їм із заплющеними очима! Просто божевілля!'::text,'довіряє'::text,'довіряти'::text,'довіряючи'::text,'Вона довіряє їм із заплющеними очима! Просто божевілля!'::text),
(324879,36098,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... en ellos con los ojos cerrados! ¡Una locura total!'::text,'confía'::text,'confiar'::text,'confiando'::text,'¡Ella confía en ellos con los ojos cerrados! ¡Una locura total!'::text),
(324878,36098,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle leur ... les yeux fermés ! Complètement fou !'::text,'fait confiance'::text,'faire confiance'::text,'faisant confiance'::text,'Elle leur fait confiance les yeux fermés ! Complètement fou !'::text),
(324881,36098,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gözleri kapalı onlara ...! Tamamen çılgınca!'::text,'güvenir'::text,'güvenmek'::text,'güvenerek'::text,'Gözleri kapalı onlara güvenir! Tamamen çılgınca!'::text),
(324882,36098,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csukott szemmel ... bennük! Teljesen őrült!'::text,'bízik'::text,'bízni'::text,'bízó'::text,'Csukott szemmel bízik bennük! Teljesen őrült!'::text),
(324894,36100,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vertrau uns! Wir ... dich auffangen, sonst ist es aus!'::text,'werden'::text,'werden'::text,'fingen'::text,'Vertrau uns! Wir werden dich auffangen, sonst ist es aus!'::text),
(324898,36100,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Довірся нам! Ми ... тебе, інакше кінець!'::text,'зловимо'::text,'зловимо'::text,'зловили'::text,'Довірся нам! Ми зловимо тебе, інакше кінець!'::text),
(324897,36100,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Confía en nosotros! ¡Nosotros te ..., o se acabó!'::text,'atraparemos'::text,'atraparemos'::text,'atrapamos'::text,'¡Confía en nosotros! ¡Nosotros te atraparemos, o se acabó!'::text),
(324896,36100,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fais-nous confiance ! Nous te ..., sinon c''est la fin !'::text,'rattraperons'::text,'rattraperons'::text,'avons rattrapé'::text,'Fais-nous confiance ! Nous te rattraperons, sinon c''est la fin !'::text),
(324899,36100,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bize güven! Seni ..., yoksa her şey biter!'::text,'yakalayacağız'::text,'yakalayacağız'::text,'yakaladık'::text,'Bize güven! Seni yakalayacağız, yoksa her şey biter!'::text),
(324900,36100,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bízz bennünk! ... téged, különben vége!'::text,'El fogunk kapni'::text,'El fogunk kapni'::text,'Elkaptunk'::text,'Bízz bennünk! El fogunk kapni téged, különben vége!'::text),
(324912,36102,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie lehnt sich mit geschlossenen Augen zurück. Sie ... ihren Händen vertrauen.'::text,'wird'::text,'wird'::text,NULL::text,'Sie lehnt sich mit geschlossenen Augen zurück. Sie wird ihren Händen vertrauen.'::text),
(324916,36102,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона відхиляється назад із заплющеними очима. Вона ... довіряти їхнім рукам.'::text,'збирається'::text,'буде'::text,NULL::text,'Вона відхиляється назад із заплющеними очима. Вона збирається довіряти їхнім рукам.'::text),
(324915,36102,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se inclina hacia atrás con los ojos cerrados. Ella ... confiar en sus manos.'::text,'va a'::text,NULL::text,NULL::text,'Se inclina hacia atrás con los ojos cerrados. Ella va a confiar en sus manos.'::text),
(324914,36102,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle se penche en arrière, les yeux fermés. Elle ... faire confiance à leurs mains.'::text,'va'::text,NULL::text,NULL::text,'Elle se penche en arrière, les yeux fermés. Elle va faire confiance à leurs mains.'::text),
(324917,36102,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gözleri kapalı geriye yaslanıyor. Onların ellerine ...'::text,'güvenecek'::text,'güvenecek'::text,NULL::text,'Gözleri kapalı geriye yaslanıyor. Onların ellerine güvenecek.'::text),
(324918,36102,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csukott szemmel hátradől. Bízni ... a kezükben.'::text,'fog'::text,'fog'::text,NULL::text,'Csukott szemmel hátradől. Bízni fog a kezükben.'::text),
(324921,36103,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, Spielregel: Das Mädchen auf der Box ... dem Team vertrauen.'::text,'muss'::text,'muss'::text,'sollte'::text,'Alter, Spielregel: Das Mädchen auf der Box muss dem Team vertrauen.'::text),
(324925,36103,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, правило гри: дівчина на ящику ... довіряти команді.'::text,'має'::text,'мусить'::text,'мала б'::text,'Бро, правило гри: дівчина на ящику має довіряти команді.'::text),
(324924,36103,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, regla del juego: la chica del cajón ... confiar en el equipo.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Tío, regla del juego: la chica del cajón tiene que confiar en el equipo.'::text),
(324923,36103,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, règle du jeu : la fille sur la box ... faire confiance à l''équipe.'::text,'doit'::text,'doit'::text,'devrait'::text,'Mec, règle du jeu : la fille sur la box doit faire confiance à l''équipe.'::text),
(324926,36103,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, oyun kuralı: kutunun üstündeki kız takıma ...'::text,'güvenmek zorunda'::text,'güvenmeli'::text,'güvenmeli'::text,'Kanka, oyun kuralı: kutunun üstündeki kız takıma güvenmek zorunda.'::text),
(324927,36103,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, játékszabály: a dobozon álló lánynak ... bíznia a csapatban.'::text,'kell'::text,'kell'::text,'kellene'::text,'Tesó, játékszabály: a dobozon álló lánynak kell bíznia a csapatban.'::text),
(324930,36104,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quartalsziel: Alle 8 Spieler ... dem Team mehr vertrauen.'::text,'sollten'::text,'sollten'::text,'sollten'::text,'Quartalsziel: Alle 8 Spieler sollten dem Team mehr vertrauen.'::text),
(324934,36104,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Квартальна ціль: усі 8 гравців ... більше довіряти команді.'::text,'мали б'::text,'мали б'::text,'мали б'::text,'Квартальна ціль: усі 8 гравців мали б більше довіряти команді.'::text),
(324933,36104,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objetivo trimestral: los 8 jugadores ... confiar más en el equipo.'::text,'deberían'::text,'deberían'::text,'deberían'::text,'Objetivo trimestral: los 8 jugadores deberían confiar más en el equipo.'::text),
(324932,36104,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objectif trimestriel : les 8 joueurs ... faire davantage confiance à l''équipe.'::text,'devraient'::text,'devraient'::text,'devraient'::text,'Objectif trimestriel : les 8 joueurs devraient faire davantage confiance à l''équipe.'::text),
(324935,36104,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çeyrek hedefi: 8 oyuncunun hepsi takıma daha çok ...'::text,'güvenmeli'::text,'güvenmeli'::text,'güvenmeli'::text,'Çeyrek hedefi: 8 oyuncunun hepsi takıma daha çok güvenmeli.'::text),
(324936,36104,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Negyedéves cél: mind a 8 játékosnak jobban ... bíznia a csapatban.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Negyedéves cél: mind a 8 játékosnak jobban kellene bíznia a csapatban.'::text),
(324939,36105,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie vertraut ihnen, ... fällt sie nach hinten, weil hinten hinter ihr ist.'::text,'also'::text,'aber'::text,'weil'::text,'Sie vertraut ihnen, also fällt sie nach hinten, weil hinten hinter ihr ist.'::text),
(324943,36105,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона їм довіряє, ... падає назад, бо назад — це позаду неї.'::text,'тому'::text,'але'::text,'бо'::text,'Вона їм довіряє, тому падає назад, бо назад — це позаду неї.'::text),
(324942,36105,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Confía en ellos, ... se deja caer hacia atrás, porque atrás está detrás de ella.'::text,'así que'::text,'pero'::text,'porque'::text,'Confía en ellos, así que se deja caer hacia atrás, porque atrás está detrás de ella.'::text),
(324941,36105,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle leur fait confiance, ... elle tombe en arrière, parce que l''arrière est derrière elle.'::text,'donc'::text,'mais'::text,'parce que'::text,'Elle leur fait confiance, donc elle tombe en arrière, parce que l''arrière est derrière elle.'::text),
(324944,36105,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlara güveniyor, ... geriye düşüyor, çünkü geri onun arkasında.'::text,'bu yüzden'::text,'ama'::text,'çünkü'::text,'Onlara güveniyor, bu yüzden geriye düşüyor, çünkü geri onun arkasında.'::text),
(324945,36105,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bízik bennük, ... hátrafelé esik, mert a hátra mögötte van.'::text,'ezért'::text,'de'::text,'mert'::text,'Bízik bennük, ezért hátrafelé esik, mert a hátra mögötte van.'::text),
(293817,32647,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Auf dem Rad ... du so schnell. Ikonisch.'::text,'bist'::text,'ist'::text,'bin'::text,'Auf dem Rad bist du so schnell. Ikonisch.'::text),
(293821,32647,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На тому велику ти ... така швидка. Легенда.'::text,'є'::text,'є'::text,'є'::text,'На тому велику ти є така швидка. Легенда.'::text),
(293820,32647,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En esa bici ... tan rápida. Icónico.'::text,'eres'::text,'es'::text,'soy'::text,'En esa bici eres tan rápida. Icónico.'::text),
(293819,32647,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sur ce vélo, tu ... trop rapide. Iconique.'::text,'es'::text,'est'::text,'suis'::text,'Sur ce vélo, tu es trop rapide. Iconique.'::text),
(293822,32647,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bisiklette çok hızlı ... İkonik.'::text,''::text,NULL::text,NULL::text,'O bisiklette çok hızlı İkonik.'::text),
(293823,32647,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan gyors ... azon a biciklin. Ikonikus.'::text,'vagy'::text,NULL::text,'vagyok'::text,'Olyan gyors vagy azon a biciklin. Ikonikus.'::text),
(293826,32648,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... mit einem schnellen Rad durch den Tunnel.'::text,'fährt'::text,'fahren'::text,'fahrend'::text,'Sie fährt mit einem schnellen Rad durch den Tunnel.'::text),
(293830,32648,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... на швидкому велосипеді через тунель.'::text,'їде'::text,'їхати'::text,'їдучи'::text,'Вона їде на швидкому велосипеді через тунель.'::text),
(293829,32648,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... en una bici rápida por el túnel.'::text,'monta'::text,'montar'::text,'montando'::text,'Ella monta en una bici rápida por el túnel.'::text),
(293828,32648,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... sur un vélo rapide à travers le tunnel.'::text,'roule'::text,'rouler'::text,'roulant'::text,'Elle roule sur un vélo rapide à travers le tunnel.'::text),
(293831,32648,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tünelden hızlı bir bisikletle ...'::text,'geçer'::text,'geçmek'::text,'geçerek'::text,'Tünelden hızlı bir bisikletle geçer.'::text),
(293832,32648,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy gyors biciklivel ... át az alagúton.'::text,'teker'::text,'tekerni'::text,'tekerő'::text,'Egy gyors biciklivel teker át az alagúton.'::text),
(293844,32650,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... im Tunnel ein schnelles Auto an ihr vorbei.'::text,'fuhr'::text,'fuhr'::text,'fährt'::text,'Gestern fuhr im Tunnel ein schnelles Auto an ihr vorbei.'::text),
(293848,32650,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора в тунелі повз неї ... швидка машина.'::text,'проїхала'::text,'проїхала'::text,'проїжджає'::text,'Учора в тунелі повз неї проїхала швидка машина.'::text),
(293847,32650,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayer un coche rápido ... a su lado en el túnel.'::text,'pasó'::text,'pasó'::text,'pasa'::text,'Ayer un coche rápido pasó a su lado en el túnel.'::text),
(293846,32650,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, une voiture rapide ... à côté d''elle dans le tunnel.'::text,'est passée'::text,'est passée'::text,'passe'::text,'Hier, une voiture rapide est passée à côté d''elle dans le tunnel.'::text),
(293849,32650,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün tünelde hızlı bir araba onun yanından ...'::text,'geçti'::text,'geçti'::text,'geçer'::text,'Dün tünelde hızlı bir araba onun yanından geçti.'::text),
(293850,32650,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap egy gyors autó ... mellette az alagútban.'::text,'elhúzott'::text,'elhúzott'::text,'elhúz'::text,'Tegnap egy gyors autó elhúzott mellette az alagútban.'::text),
(293853,32651,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise erreicht sie ihr Ziel, aber gestern ... sie 40 km schnell.'::text,'fuhr'::text,'fährt'::text,NULL::text,'Normalerweise erreicht sie ihr Ziel, aber gestern fuhr sie 40 km schnell.'::text),
(293857,32651,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай вона виконує свою ціль, але вчора ... 40 км швидко.'::text,'проїхала'::text,'проїжджає'::text,NULL::text,'Зазвичай вона виконує свою ціль, але вчора проїхала 40 км швидко.'::text),
(293856,32651,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente cumple su objetivo, pero ayer ... 40 km rápido.'::text,'recorrió'::text,'recorre'::text,NULL::text,'Normalmente cumple su objetivo, pero ayer recorrió 40 km rápido.'::text),
(293855,32651,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude, elle atteint son objectif, mais hier elle ... 40 km à toute vitesse.'::text,'a parcouru'::text,'parcourt'::text,NULL::text,'D''habitude, elle atteint son objectif, mais hier elle a parcouru 40 km à toute vitesse.'::text),
(293858,32651,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde hedefini tutturur ama dün 40 km''yi hızlı ...'::text,'sürdü'::text,'sürer'::text,NULL::text,'Genelde hedefini tutturur ama dün 40 km''yi hızlı sürdü.'::text),
(293859,32651,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában teljesíti a célját, de tegnap gyorsan ... 40 km-t.'::text,'tekert'::text,'teker'::text,NULL::text,'Általában teljesíti a célját, de tegnap gyorsan tekert 40 km-t.'::text),
(293862,32652,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Auto war ... als ihr Rad, also fuhr es an ihr vorbei.'::text,'schneller'::text,'schneller'::text,'am schnellsten'::text,'Das Auto war schneller als ihr Rad, also fuhr es an ihr vorbei.'::text),
(293866,32652,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Машина була ... за її велосипед, тому проїхала повз неї.'::text,'швидша'::text,'більш швидка'::text,'найшвидша'::text,'Машина була швидша за її велосипед, тому проїхала повз неї.'::text),
(293865,32652,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El coche era ... que su bici, así que la adelantó.'::text,'más rápido'::text,'más rápido'::text,'el más rápido'::text,'El coche era más rápido que su bici, así que la adelantó.'::text),
(293864,32652,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La voiture était ... que son vélo, alors elle l''a dépassée.'::text,'plus rapide'::text,'plus rapide'::text,'la plus rapide'::text,'La voiture était plus rapide que son vélo, alors elle l''a dépassée.'::text),
(293867,32652,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Araba onun bisikletinden ..., bu yüzden yanından geçti.'::text,'daha hızlıydı'::text,'daha hızlıydı'::text,'en hızlıydı'::text,'Araba onun bisikletinden daha hızlıydı, bu yüzden yanından geçti.'::text),
