(325967,36219,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mamie a deux ... aujourd''hui.'::text,'visiteurs'::text,'visiteur'::text,'visiteurs'::text,'Mamie a deux visiteurs aujourd''hui.'::text),
(325970,36219,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyükannenin bugün iki ... var.'::text,'misafiri'::text,'misafiri'::text,'misafiri'::text,'Büyükannenin bugün iki misafiri var.'::text),
(325971,36219,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagymamának ma két ... van.'::text,'vendége'::text,'vendége'::text,'vendége'::text,'A nagymamának ma két vendége van.'::text),
(325974,36220,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, eine Tortenschachtel? Das ist ... Besucher mit Manieren, Alter.'::text,'ein'::text,'ein'::text,'der'::text,'Ey, eine Tortenschachtel? Das ist ein Besucher mit Manieren, Alter.'::text),
(325978,36220,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, коробка з тортом? Це ... гість із манерами, бро.'::text,''::text,NULL::text,NULL::text,'Йо, коробка з тортом? Це гість із манерами, бро.'::text),
(325977,36220,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, ¿una caja de tarta? Eso es ... visita con modales, tío.'::text,'una'::text,'una'::text,'la'::text,'Oye, ¿una caja de tarta? Eso es una visita con modales, tío.'::text),
(325976,36220,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, une boîte à gâteau ? Ça, c''est ... visiteur bien élevé, frère.'::text,'un'::text,'un'::text,'le'::text,'Wesh, une boîte à gâteau ? Ça, c''est un visiteur bien élevé, frère.'::text),
(325979,36220,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, pasta kutusu mu? Bu ... görgülü misafir, dostum.'::text,'bir'::text,'bir'::text,NULL::text,'Kanka, pasta kutusu mu? Bu bir görgülü misafir, dostum.'::text),
(325980,36220,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, tortásdoboz? Ez ... jól nevelt vendég, tesó.'::text,'egy'::text,'egy'::text,'a'::text,'Figyu, tortásdoboz? Ez egy jól nevelt vendég, tesó.'::text),
(325983,36221,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budgetnotiz: ... Besucher bringen eine Torte für 20 Euro mit.'::text,'Diese'::text,'Dieser'::text,'Jener'::text,'Budgetnotiz: Diese Besucher bringen eine Torte für 20 Euro mit.'::text),
(325987,36221,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бюджетна примітка: ... гості приносять торт за 20 євро.'::text,'ці'::text,'цей'::text,'той'::text,'Бюджетна примітка: ці гості приносять торт за 20 євро.'::text),
(325986,36221,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nota de presupuesto: ... visitas traen una tarta de 20 euros.'::text,'estas'::text,'esta'::text,'esa'::text,'Nota de presupuesto: estas visitas traen una tarta de 20 euros.'::text),
(325985,36221,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Note budgétaire : ... visiteurs apportent un gâteau à 20 euros.'::text,'ces'::text,'ce'::text,'ce'::text,'Note budgétaire : ces visiteurs apportent un gâteau à 20 euros.'::text),
(325988,36221,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütçe notu: ... misafirler 20 euroluk bir pasta getiriyor.'::text,'bu'::text,'bu'::text,'şu'::text,'Bütçe notu: bu misafirler 20 euroluk bir pasta getiriyor.'::text),
(325989,36221,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Költségvetési megjegyzés: ... a vendégek egy 20 eurós tortát hoznak.'::text,'ezek'::text,'ez'::text,'az'::text,'Költségvetési megjegyzés: ezek a vendégek egy 20 eurós tortát hoznak.'::text),
(325992,36222,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Besucher umarmen ... Oma, weil sie ihre Oma ist.'::text,'ihre'::text,'seine'::text,'seine'::text,'Die Besucher umarmen ihre Oma, weil sie ihre Oma ist.'::text),
(325996,36222,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гості обіймають ... бабусю, бо вона їхня бабуся.'::text,'свою'::text,'його'::text,'його'::text,'Гості обіймають свою бабусю, бо вона їхня бабуся.'::text),
(325995,36222,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las visitas abrazan a ... abuela porque es su abuela.'::text,'su'::text,'su'::text,'su'::text,'Las visitas abrazan a su abuela porque es su abuela.'::text),
(325994,36222,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les visiteurs serrent ... grand-mère dans leurs bras parce que c''est leur grand-mère.'::text,'leur'::text,'sa'::text,'sa'::text,'Les visiteurs serrent leur grand-mère dans leurs bras parce que c''est leur grand-mère.'::text),
(325997,36222,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Misafirler ... büyükannelerine sarılıyor çünkü o onların büyükannesi.'::text,'onların'::text,'onun'::text,'onun'::text,'Misafirler onların büyükannelerine sarılıyor çünkü o onların büyükannesi.'::text),
(325998,36222,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vendégek megölelik a ..., mert ő a nagymamájuk.'::text,'nagymamájukat'::text,'nagymamáját'::text,'nagymamáját'::text,'A vendégek megölelik a nagymamájukat, mert ő a nagymamájuk.'::text),
(326001,36223,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sind die Besucher? Absolut keine Ahnung!'::text,'Wer'::text,'Was'::text,'Wo'::text,'Wer sind die Besucher? Absolut keine Ahnung!'::text),
(326005,36223,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ці гості? Гадки не маю!'::text,'Хто'::text,'Що'::text,'Де'::text,'Хто ці гості? Гадки не маю!'::text),
(326004,36223,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... son las visitas? ¡Ni idea!'::text,'Quiénes'::text,'Qué'::text,'Dónde'::text,'¿Quiénes son las visitas? ¡Ni idea!'::text),
(326003,36223,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sont les visiteurs ? Aucune idée !'::text,'Qui'::text,'Que'::text,'Où'::text,'Qui sont les visiteurs ? Aucune idée !'::text),
(326006,36223,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Misafirler ...? Hiçbir fikrim yok!'::text,'kim'::text,'ne'::text,'nerede'::text,'Misafirler kim? Hiçbir fikrim yok!'::text),
(326007,36223,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a vendégek? Fogalmam sincs!'::text,'Kik'::text,'Mik'::text,'Hol'::text,'Kik a vendégek? Fogalmam sincs!'::text),
(326010,36224,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Besucher stehen ... der Tür! Einfach unglaublich!'::text,'vor'::text,'in'::text,'auf'::text,'Die Besucher stehen vor der Tür! Einfach unglaublich!'::text),
(326014,36224,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гості ... дверей! Просто неймовірно!'::text,'біля'::text,'в'::text,'на'::text,'Гості біля дверей! Просто неймовірно!'::text),
(326013,36224,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Las visitas están ... la puerta! ¡Increíble!'::text,'en'::text,'en'::text,'sobre'::text,'¡Las visitas están en la puerta! ¡Increíble!'::text),
(326012,36224,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les visiteurs sont ... la porte ! Absolument génial !'::text,'à'::text,'dans'::text,'sur'::text,'Les visiteurs sont à la porte ! Absolument génial !'::text),
(326015,36224,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Misafirler kapı ...! İnanılmaz!'::text,''::text,'içinde'::text,'üstünde'::text,'Misafirler kapı! İnanılmaz!'::text),
(326016,36224,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vendégek ... állnak! Egyszerűen csodás!'::text,'az ajtónál'::text,'az ajtóban'::text,'az ajtón'::text,'A vendégek az ajtónál állnak! Egyszerűen csodás!'::text),
(316506,35168,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, normalerweise laufen wir an Werbetafeln vorbei, aber gestern ... wir jede einzelne an.'::text,'starrten'::text,'starren'::text,NULL::text,'Alter, normalerweise laufen wir an Werbetafeln vorbei, aber gestern starrten wir jede einzelne an.'::text),
(316510,35168,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, зазвичай ми проходимо повз рекламу, але вчора ... на кожну.'::text,'витріщалися'::text,'витріщаємося'::text,NULL::text,'Бро, зазвичай ми проходимо повз рекламу, але вчора витріщалися на кожну.'::text),
(316509,35168,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, normalmente pasamos de largo de los carteles, pero ayer ... cada uno.'::text,'miramos fijamente'::text,'miramos fijamente'::text,NULL::text,'Tío, normalmente pasamos de largo de los carteles, pero ayer miramos fijamente cada uno.'::text),
(316508,35168,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, d''habitude nous passons devant les panneaux, mais hier nous ... chacun d''eux.'::text,'avons fixé'::text,'fixons'::text,NULL::text,'Mec, d''habitude nous passons devant les panneaux, mais hier nous avons fixé chacun d''eux.'::text),
(316511,35168,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, genelde tabelaların önünden geçer gideriz ama dün her birine dik dik ...'::text,'baktık'::text,'bakarız'::text,NULL::text,'Kanka, genelde tabelaların önünden geçer gideriz ama dün her birine dik dik baktık.'::text),
(316512,35168,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, általában elsétálunk a reklámtáblák mellett, de tegnap mindegyiket ...'::text,'bámultuk'::text,'bámuljuk'::text,NULL::text,'Tesó, általában elsétálunk a reklámtáblák mellett, de tegnap mindegyiket bámultuk.'::text),
(316515,35169,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, schau, diese riesigen Werbetafeln ... gerade hell.'::text,'leuchten'::text,'leuchten'::text,'leuchten'::text,'Ey, schau, diese riesigen Werbetafeln leuchten gerade hell.'::text),
(316519,35169,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, глянь, ті величезні рекламні щити саме зараз яскраво ...'::text,'світяться'::text,'світяться'::text,'світяться'::text,'Йо, глянь, ті величезні рекламні щити саме зараз яскраво світяться.'::text),
(316518,35169,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, mira, esos carteles enormes ... con fuerza ahora mismo.'::text,'están brillando'::text,'brillan'::text,'están brillando'::text,'Oye, mira, esos carteles enormes están brillando con fuerza ahora mismo.'::text),
(316517,35169,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, regarde, ces panneaux géants ... fort en ce moment.'::text,'sont en train de briller'::text,'brillent'::text,'sont en train de briller'::text,'Wesh, regarde, ces panneaux géants sont en train de briller fort en ce moment.'::text),
(316520,35169,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka bak, şu devasa tabelalar şu an parlak parlak ...'::text,'parlıyor'::text,'parlar'::text,'parlıyor'::text,'Kanka bak, şu devasa tabelalar şu an parlak parlak parlıyor.'::text),
(316521,35169,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, nézd, azok az óriási reklámtáblák most épp fényesen ...'::text,'világítanak'::text,'világítanak'::text,'világítanak'::text,'Figyu, nézd, azok az óriási reklámtáblák most épp fényesen világítanak.'::text),
(316524,35170,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Werbetafeln zeigen normalerweise 3 Marken, aber heute ... sie eine neue Kampagne.'::text,'zeigen'::text,'zeigen'::text,NULL::text,'Die Werbetafeln zeigen normalerweise 3 Marken, aber heute zeigen sie eine neue Kampagne.'::text),
(316528,35170,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рекламні щити зазвичай показують 3 бренди, але сьогодні ... нову кампанію.'::text,'показують'::text,'показують'::text,NULL::text,'Рекламні щити зазвичай показують 3 бренди, але сьогодні показують нову кампанію.'::text),
(316527,35170,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los carteles suelen mostrar 3 marcas, pero hoy ... una nueva campaña.'::text,'están mostrando'::text,'muestran'::text,NULL::text,'Los carteles suelen mostrar 3 marcas, pero hoy están mostrando una nueva campaña.'::text),
(316526,35170,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les panneaux affichent d''habitude 3 marques, mais aujourd''hui ils ... une nouvelle campagne.'::text,'sont en train d''afficher'::text,'affichent'::text,NULL::text,'Les panneaux affichent d''habitude 3 marques, mais aujourd''hui ils sont en train d''afficher une nouvelle campagne.'::text),
(316529,35170,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabelalar genelde 3 marka gösterir ama bugün yeni bir kampanya ...'::text,'gösteriyor'::text,'gösterir'::text,NULL::text,'Tabelalar genelde 3 marka gösterir ama bugün yeni bir kampanya gösteriyor.'::text),
(316530,35170,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A reklámtáblák általában 3 márkát mutatnak, de ma egy új kampányt ...'::text,'mutatnak'::text,'mutatnak'::text,NULL::text,'A reklámtáblák általában 3 márkát mutatnak, de ma egy új kampányt mutatnak.'::text),
(316533,35171,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heute Abend ... die Leute diese große Werbetafel sehen, weil sie groß ist.'::text,'werden'::text,'sind'::text,NULL::text,'Heute Abend werden die Leute diese große Werbetafel sehen, weil sie groß ist.'::text),
(316537,35171,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні ввечері люди ... бачити цю велику рекламу, бо вона велика.'::text,'будуть'::text,'є'::text,NULL::text,'Сьогодні ввечері люди будуть бачити цю велику рекламу, бо вона велика.'::text),
(316536,35171,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta noche la gente ... ver ese cartel grande, porque es grande.'::text,''::text,'está'::text,NULL::text,'Esta noche la gente ver ese cartel grande, porque es grande.'::text),
(316535,35171,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce soir, les gens ... voir ce grand panneau, parce qu''il est grand.'::text,''::text,'sont'::text,NULL::text,'Ce soir, les gens voir ce grand panneau, parce qu''il est grand.'::text),
(316538,35171,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşam insanlar o büyük tabelayı ..., çünkü büyük.'::text,'görecek'::text,NULL::text,NULL::text,'Bu akşam insanlar o büyük tabelayı görecek, çünkü büyük.'::text),
(316539,35171,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma este az emberek ... látni azt a nagy reklámtáblát, mert nagy.'::text,'fogják'::text,'vannak'::text,NULL::text,'Ma este az emberek fogják látni azt a nagy reklámtáblát, mert nagy.'::text),
(316542,35172,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat einen Plan. Sie ... ein Selfie unter den Werbetafeln machen.'::text,'wird'::text,'werden'::text,'wird'::text,'Sie hat einen Plan. Sie wird ein Selfie unter den Werbetafeln machen.'::text),
(316546,35172,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У неї є план. Вона ... зробити селфі під рекламними щитами.'::text,'збирається'::text,'збираються'::text,'збирається'::text,'У неї є план. Вона збирається зробити селфі під рекламними щитами.'::text),
(316545,35172,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiene un plan. Ella ... hacerse un selfie bajo los carteles.'::text,'va a'::text,'van a'::text,'va a'::text,'Tiene un plan. Ella va a hacerse un selfie bajo los carteles.'::text),
(316544,35172,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a un plan. Elle ... prendre un selfie sous les panneaux.'::text,'va'::text,'vont'::text,'va'::text,'Elle a un plan. Elle va prendre un selfie sous les panneaux.'::text),
(316547,35172,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir planı var. Tabelaların altında selfie ...'::text,'çekecek'::text,'çekecekler'::text,'çekecek'::text,'Bir planı var. Tabelaların altında selfie çekecek.'::text),
(316548,35172,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Van egy terve. Szelfit ... készíteni a reklámtáblák alatt.'::text,'fog'::text,'fognak'::text,'fog'::text,'Van egy terve. Szelfit fog készíteni a reklámtáblák alatt.'::text),
(316560,35174,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schön für die Stadt: Die Werbetafeln verbrauchen heute Abend sehr wenig ...'::text,'Strom'::text,'Strom'::text,'einen Strom'::text,'Schön für die Stadt: Die Werbetafeln verbrauchen heute Abend sehr wenig Strom.'::text),
(316564,35174,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Як же добре для міста: рекламні щити сьогодні ввечері споживають дуже мало ...'::text,'електрики'::text,'електрики'::text,'електрики'::text,'Як же добре для міста: рекламні щити сьогодні ввечері споживають дуже мало електрики.'::text),
(316563,35174,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué bien para la ciudad: los carteles gastan muy poca ... esta noche.'::text,'electricidad'::text,'electricidad'::text,'una electricidad'::text,'Qué bien para la ciudad: los carteles gastan muy poca electricidad esta noche.'::text),
(316562,35174,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trop bien pour la ville : les panneaux consomment très peu d''... ce soir.'::text,'électricité'::text,'électricité'::text,'une électricité'::text,'Trop bien pour la ville : les panneaux consomment très peu d''électricité ce soir.'::text),
(316565,35174,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şehir adına çok sevindim: tabelalar bu akşam çok az ... harcıyor.'::text,'elektrik'::text,'elektrikler'::text,'bir elektrik'::text,'Şehir adına çok sevindim: tabelalar bu akşam çok az elektrik harcıyor.'::text),
(316566,35174,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'De jó a városnak: a reklámtáblák ma este nagyon kevés ... fogyasztanak.'::text,'áramot'::text,'áramot'::text,'egy áramot'::text,'De jó a városnak: a reklámtáblák ma este nagyon kevés áramot fogyasztanak.'::text),
(316569,35175,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich eine ruhige Straße: Hier sind nicht ... Werbetafeln.'::text,'viele'::text,'viel'::text,'einige'::text,'Offensichtlich eine ruhige Straße: Hier sind nicht viele Werbetafeln.'::text),
(316573,35175,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, тиха вулиця: тут немає ... рекламних щитів.'::text,'багато'::text,'багато'::text,'якихось'::text,'Очевидно, тиха вулиця: тут немає багато рекламних щитів.'::text),
(316572,35175,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente una calle tranquila: aquí no hay ... carteles.'::text,'muchos'::text,'mucho'::text,'algunos'::text,'Obviamente una calle tranquila: aquí no hay muchos carteles.'::text),
(316571,35175,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment une rue calme : il n''y a pas ... panneaux ici.'::text,'beaucoup de'::text,'beaucoup de'::text,'des'::text,'Évidemment une rue calme : il n''y a pas beaucoup de panneaux ici.'::text),
(316574,35175,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki sakin bir sokak: burada ... tabela yok.'::text,'çok'::text,'çok'::text,'bazı'::text,'Belli ki sakin bir sokak: burada çok tabela yok.'::text),
(316575,35175,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván csendes utca: itt nincs ... reklámtábla.'::text,'sok'::text,'sok'::text,'néhány'::text,'Nyilván csendes utca: itt nincs sok reklámtábla.'::text),
(322113,35791,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... eine riesige Aufgabe an der Spüle.'::text,'hat'::text,'haben'::text,'hat'::text,'Er hat eine riesige Aufgabe an der Spüle.'::text),
(322117,35791,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... величезне завдання біля раковини.'::text,'має'::text,'мати'::text,'має'::text,'Він має величезне завдання біля раковини.'::text),
(322116,35791,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... una tarea enorme en el fregadero.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'Él tiene una tarea enorme en el fregadero.'::text),
(322115,35791,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... une tâche énorme à l''évier.'::text,'a'::text,'ont'::text,'a'::text,'Il a une tâche énorme à l''évier.'::text),
(322118,35791,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lavaboda onun devasa bir görevi ...'::text,'var'::text,'var'::text,'var'::text,'Lavaboda onun devasa bir görevi var.'::text),
(322119,35791,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neki ... egy óriási feladata a mosogatónál.'::text,'van'::text,'van'::text,'van'::text,'Neki van egy óriási feladata a mosogatónál.'::text),
(322131,35793,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nein! Er hat heute hundert ...! Schrecklich!'::text,'Aufgaben'::text,'Aufgabe'::text,'Aufgaben'::text,'Nein! Er hat heute hundert Aufgaben! Schrecklich!'::text),
(322135,35793,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ні! Він має сьогодні сто ...! Жахливо!'::text,'завдань'::text,'завдання'::text,'завдань'::text,'Ні! Він має сьогодні сто завдань! Жахливо!'::text),
(322134,35793,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No! ¡Hoy tiene cien ...! ¡Horrible!'::text,'tareas'::text,'tarea'::text,'tareas'::text,'¡No! ¡Hoy tiene cien tareas! ¡Horrible!'::text),
(322133,35793,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non ! Il a cent ... aujourd''hui ! Horrible !'::text,'tâches'::text,'tâche'::text,'tâches'::text,'Non ! Il a cent tâches aujourd''hui ! Horrible !'::text),
(322136,35793,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayır! Bugün onun yüz ... var! Korkunç!'::text,'görevi'::text,'görevi'::text,'görevi'::text,'Hayır! Bugün onun yüz görevi var! Korkunç!'::text),
(322137,35793,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne! Ma száz ... van! Szörnyű!'::text,'feladata'::text,'feladata'::text,'feladata'::text,'Ne! Ma száz feladata van! Szörnyű!'::text),
(322140,35794,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ist ... schlimmste Aufgabe der Welt! Ein Albtraum!'::text,'die'::text,'eine'::text,'eine'::text,'Das ist die schlimmste Aufgabe der Welt! Ein Albtraum!'::text),
(322144,35794,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це ... найгірше завдання у світі! Жах!'::text,''::text,NULL::text,NULL::text,'Це найгірше завдання у світі! Жах!'::text),
(322143,35794,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Esta es ... peor tarea del mundo! ¡Una pesadilla!'::text,'la'::text,'una'::text,'una'::text,'¡Esta es la peor tarea del mundo! ¡Una pesadilla!'::text),
(322142,35794,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est ... pire tâche du monde ! Un cauchemar !'::text,'la'::text,'une'::text,'une'::text,'C''est la pire tâche du monde ! Un cauchemar !'::text),
(322145,35794,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu dünyadaki ... en kötü görev! Kâbus!'::text,''::text,'bir'::text,'bir'::text,'Bu dünyadaki en kötü görev! Kâbus!'::text),
(322146,35794,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez ... legrosszabb feladat a világon! Rémálom!'::text,'a'::text,'egy'::text,'egy'::text,'Ez a legrosszabb feladat a világon! Rémálom!'::text),
(322158,35796,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beste, seine Mama hat gesagt, er ... heute Abend die ganze Aufgabe fertig machen.'::text,'muss'::text,'muss'::text,'sollte'::text,'Beste, seine Mama hat gesagt, er muss heute Abend die ganze Aufgabe fertig machen.'::text),
(322162,35796,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, його мама сказала, що він ... сьогодні ввечері закінчити все завдання.'::text,'має'::text,'мусить'::text,'мав би'::text,'Подруго, його мама сказала, що він має сьогодні ввечері закінчити все завдання.'::text),
(322161,35796,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, su madre dijo que él ... terminar toda la tarea esta noche.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Amiga, su madre dijo que él tiene que terminar toda la tarea esta noche.'::text),
(322160,35796,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, sa mère a dit qu''il ... finir toute la tâche ce soir.'::text,'doit'::text,'doit'::text,'devrait'::text,'Ma belle, sa mère a dit qu''il doit finir toute la tâche ce soir.'::text),
(322163,35796,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kankiş, annesi demiş ki bu akşam bütün işi ...'::text,'bitirmek zorunda'::text,'bitirmeli'::text,'bitirmeli'::text,'Kankiş, annesi demiş ki bu akşam bütün işi bitirmek zorunda.'::text),
(322164,35796,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, az anyukája azt mondta, hogy ma este be ... fejeznie az egész feladatot.'::text,'kell'::text,'kell'::text,'kellene'::text,'Csajszi, az anyukája azt mondta, hogy ma este be kell fejeznie az egész feladatot.'::text),
(322167,35797,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, die Aufgabe ist viel zu groß, du ... dir eine Spülmaschine holen.'::text,'solltest'::text,'solltest'::text,'solltest'::text,'Alter, die Aufgabe ist viel zu groß, du solltest dir eine Spülmaschine holen.'::text),
(322171,35797,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, це завдання надто велике, ти ... купити посудомийку.'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Бро, це завдання надто велике, ти мав би купити посудомийку.'::text),
(322170,35797,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, esta tarea es demasiado grande, ... pillarte un lavavajillas.'::text,'deberías'::text,'deberías'::text,'deberías'::text,'Tío, esta tarea es demasiado grande, deberías pillarte un lavavajillas.'::text),
(322169,35797,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, cette tâche est bien trop grosse, tu ... prendre un lave-vaisselle.'::text,'devrais'::text,'devrais'::text,'devrais'::text,'Mec, cette tâche est bien trop grosse, tu devrais prendre un lave-vaisselle.'::text),
(322172,35797,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu iş fazla büyük, bir bulaşık makinesi ...'::text,'almalısın'::text,'almalısın'::text,'almalısın'::text,'Kanka, bu iş fazla büyük, bir bulaşık makinesi almalısın.'::text),
(322173,35797,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ez a feladat túl nagy, venned ... egy mosogatógépet.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Tesó, ez a feladat túl nagy, venned kellene egy mosogatógépet.'::text),
(322176,35798,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er versucht, die Aufgabe fertig zu kriegen, ... die Teller hören nie auf.'::text,'aber'::text,'also'::text,'weil'::text,'Alter, er versucht, die Aufgabe fertig zu kriegen, aber die Teller hören nie auf.'::text),
(322180,35798,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, він пробує доробити завдання, ... тарілки не закінчуються.'::text,'але'::text,'тому'::text,'бо'::text,'Чувак, він пробує доробити завдання, але тарілки не закінчуються.'::text),
(322179,35798,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, intenta acabar la tarea, ... los platos no se acaban nunca.'::text,'pero'::text,'así que'::text,'porque'::text,'Tío, intenta acabar la tarea, pero los platos no se acaban nunca.'::text),
(322178,35798,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il essaie de finir la tâche, ... les assiettes ne finissent jamais.'::text,'mais'::text,'donc'::text,'parce que'::text,'Mec, il essaie de finir la tâche, mais les assiettes ne finissent jamais.'::text),
(322181,35798,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, işi bitirmeye çalışıyor ... tabaklar hiç bitmiyor.'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Kanka, işi bitirmeye çalışıyor ama tabaklar hiç bitmiyor.'::text),
(322182,35798,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, próbálja befejezni a feladatot, ... a tányérok sosem fogynak el.'::text,'de'::text,'ezért'::text,'mert'::text,'Haver, próbálja befejezni a feladatot, de a tányérok sosem fogynak el.'::text),
(309675,34409,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ist mein weißes T-Shirt? Rosa? Oh nein, Katastrophe!'::text,'Wo'::text,'Wer'::text,'Wann'::text,'Wo ist mein weißes T-Shirt? Rosa? Oh nein, Katastrophe!'::text),
(309679,34409,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... моя біла футболка? Рожева? О ні, катастрофа!'::text,'Де'::text,'Хто'::text,'Коли'::text,'Де моя біла футболка? Рожева? О ні, катастрофа!'::text),
(309678,34409,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... está mi camiseta blanca? ¿Rosa? ¡Oh, no, qué desastre!'::text,'Dónde'::text,'Quién'::text,'Cuándo'::text,'¿Dónde está mi camiseta blanca? ¿Rosa? ¡Oh, no, qué desastre!'::text),
(309677,34409,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... est mon t-shirt blanc ? Rose ? Oh non, catastrophe !'::text,'Où'::text,'Qui'::text,'Quand'::text,'Où est mon t-shirt blanc ? Rose ? Oh non, catastrophe !'::text),
(309680,34409,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beyaz tişörtüm ...? Pembe mi? Olamaz, felaket!'::text,'nerede'::text,'kim'::text,'ne zaman'::text,'Beyaz tişörtüm nerede? Pembe mi? Olamaz, felaket!'::text),
(309681,34409,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... van a fehér pólóm? Rózsaszín? Jaj ne, katasztrófa!'::text,'Hol'::text,'Ki'::text,'Mikor'::text,'Hol van a fehér pólóm? Rózsaszín? Jaj ne, katasztrófa!'::text),
(309684,34410,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, sie hat gesagt, sie ... sich letzte Woche die Haare pink.'::text,'färbte'::text,'färbt'::text,'färben'::text,'Rate mal, sie hat gesagt, sie färbte sich letzte Woche die Haare pink.'::text),
(309688,34410,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, вона сказала, що минулого тижня ... волосся в рожевий.'::text,'пофарбувала'::text,'фарбує'::text,'фарбувати'::text,'Уяви, вона сказала, що минулого тижня пофарбувала волосся в рожевий.'::text),
(309687,34410,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina, dijo que la semana pasada se ... el pelo de rosa.'::text,'tiñó'::text,'tiñe'::text,'teñir'::text,'Adivina, dijo que la semana pasada se tiñó el pelo de rosa.'::text),
(309686,34410,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, elle a dit qu''elle ... les cheveux en rose la semaine dernière.'::text,'s''est teint'::text,'se teint'::text,'se teindre'::text,'Devine quoi, elle a dit qu''elle s''est teint les cheveux en rose la semaine dernière.'::text),
(309689,34410,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, dedi ki geçen hafta saçını pembeye ...'::text,'boyadı'::text,'boyar'::text,'boyamak'::text,'Bil bakalım, dedi ki geçen hafta saçını pembeye boyadı.'::text),
(309690,34410,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt mondta, hogy múlt héten rózsaszínre ... a haját.'::text,'festette'::text,'festi'::text,'festeni'::text,'Képzeld, azt mondta, hogy múlt héten rózsaszínre festette a haját.'::text),
(309693,34411,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, pinke Haare, aber ich hab gehört, sie ... gestern ein weißes Hemd.'::text,'wusch'::text,'wäscht'::text,NULL::text,'Mädel, pinke Haare, aber ich hab gehört, sie wusch gestern ein weißes Hemd.'::text),
(309697,34411,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, рожеве волосся, але я чула, що вчора вона ... білу сорочку.'::text,'прала'::text,'пере'::text,NULL::text,'Подруго, рожеве волосся, але я чула, що вчора вона прала білу сорочку.'::text),
(309696,34411,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, pelo rosa, pero he oído que ayer ... una camisa blanca.'::text,'lavó'::text,'lava'::text,NULL::text,'Tía, pelo rosa, pero he oído que ayer lavó una camisa blanca.'::text),
(309695,34411,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, cheveux roses, mais il paraît qu''hier elle ... une chemise blanche.'::text,'a lavé'::text,'lave'::text,NULL::text,'Meuf, cheveux roses, mais il paraît qu''hier elle a lavé une chemise blanche.'::text),
(309698,34411,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, saçlar pembe ama duyduğuma göre dün beyaz bir gömlek ...'::text,'yıkadı'::text,'yıkar'::text,NULL::text,'Kızım, saçlar pembe ama duyduğuma göre dün beyaz bir gömlek yıkadı.'::text),
(309699,34411,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, rózsaszín haj, de azt hallottam, hogy tegnap egy fehér inget ...'::text,'mosott'::text,'mos'::text,NULL::text,'Csajszi, rózsaszín haj, de azt hallottam, hogy tegnap egy fehér inget mosott.'::text),
(309702,34412,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ey, sie ... ihre Klamotten rein, überall pinke Haare, irgendwie ikonisch.'::text,'stopft'::text,'stopft'::text,'stopft'::text,'Ey, sie stopft ihre Klamotten rein, überall pinke Haare, irgendwie ikonisch.'::text),
(309706,34412,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, вона ... одяг усередину, всюди рожеве волосся, трохи легендарно.'::text,'закидає'::text,'закидає'::text,'закидає'::text,'Йо, вона закидає одяг усередину, всюди рожеве волосся, трохи легендарно.'::text),
(309705,34412,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, ella ... la ropa dentro, pelo rosa por todas partes, en plan icónico.'::text,'está metiendo'::text,'está metiendo'::text,'está metiendo'::text,'Oye, ella está metiendo la ropa dentro, pelo rosa por todas partes, en plan icónico.'::text),
(309704,34412,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, elle ... ses fringues dedans, des cheveux roses partout, un peu iconique.'::text,'est en train de mettre'::text,'est en train de mettre'::text,'est en train de mettre'::text,'Wesh, elle est en train de mettre ses fringues dedans, des cheveux roses partout, un peu iconique.'::text),
(309707,34412,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kıyafetlerini içeri ..., her yer pembe saç, resmen ikonik.'::text,'atıyor'::text,'atıyor'::text,'atıyor'::text,'Kanka, kıyafetlerini içeri atıyor, her yer pembe saç, resmen ikonik.'::text),
(309708,34412,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, ... a ruháit, mindenhol rózsaszín haj, kicsit ikonikus.'::text,'bepakolja'::text,'bepakolja'::text,'bepakolja'::text,'Figyu, bepakolja a ruháit, mindenhol rózsaszín haj, kicsit ikonikus.'::text),
(309711,34413,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee, Pink ist ihr Vibe, aber gerade ... sie ein weißes Shirt.'::text,'wäscht'::text,'wäscht'::text,NULL::text,'Nee, Pink ist ihr Vibe, aber gerade wäscht sie ein weißes Shirt.'::text),
(309715,34413,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не, рожевий — це її вайб, але зараз вона ... білу футболку.'::text,'пере'::text,'пере'::text,NULL::text,'Не, рожевий — це її вайб, але зараз вона пере білу футболку.'::text),
(309714,34413,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, el rosa es su rollo, pero ahora mismo ... una camiseta blanca.'::text,'está lavando'::text,'lava'::text,NULL::text,'Qué va, el rosa es su rollo, pero ahora mismo está lavando una camiseta blanca.'::text),
(309713,34413,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nan, le rose c''est son vibe, mais là elle ... un t-shirt blanc.'::text,'est en train de laver'::text,'lave'::text,NULL::text,'Nan, le rose c''est son vibe, mais là elle est en train de laver un t-shirt blanc.'::text),
(309716,34413,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok, pembe onun tarzı ama şu an beyaz bir tişört ...'::text,'yıkıyor'::text,'yıkar'::text,NULL::text,'Yok, pembe onun tarzı ama şu an beyaz bir tişört yıkıyor.'::text),
(309717,34413,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, a rózsaszín az ő vibe-ja, de most épp egy fehér pólót ...'::text,'mos'::text,'mos'::text,NULL::text,'Á, a rózsaszín az ő vibe-ja, de most épp egy fehér pólót mos.'::text),
(309729,34415,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau mit den pinken Haaren lächelt ...'::text,'fröhlich.'::text,'fröhlich.'::text,'Fröhlichkeit.'::text,'Die Frau mit den pinken Haaren lächelt fröhlich.'::text),
(309733,34415,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка з рожевим волоссям усміхається ...'::text,'радісно.'::text,'радісний.'::text,'радість.'::text,'Жінка з рожевим волоссям усміхається радісно.'::text),
(309732,34415,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer del pelo rosa sonríe ...'::text,'felizmente.'::text,'feliz.'::text,'felicidad.'::text,'La mujer del pelo rosa sonríe felizmente.'::text),
(309731,34415,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme aux cheveux roses sourit ...'::text,'joyeusement.'::text,'joyeux.'::text,'joie.'::text,'La femme aux cheveux roses sourit joyeusement.'::text),
(309734,34415,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pembe saçlı kadın gülümsüyor, hem de ...'::text,'mutluca.'::text,'mutlu.'::text,'mutluluk.'::text,'Pembe saçlı kadın gülümsüyor, hem de mutluca.'::text),
(309735,34415,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rózsaszín hajú nő mosolyog, méghozzá ...'::text,'boldogan.'::text,'boldog.'::text,'boldogság.'::text,'A rózsaszín hajú nő mosolyog, méghozzá boldogan.'::text),
(294825,32759,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... einen süßen Blumentopf auf deiner Fensterbank. Respekt.'::text,'hast'::text,'hat'::text,'hast'::text,'Du hast einen süßen Blumentopf auf deiner Fensterbank. Respekt.'::text),
(294829,32759,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... милий вазон на підвіконні. Респект.'::text,'маєш'::text,'має'::text,'маєш'::text,'Ти маєш милий вазон на підвіконні. Респект.'::text),
(294828,32759,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... una maceta muy mona en la ventana. Respeto.'::text,'Tienes'::text,'Tiene'::text,'Tienes'::text,'Tienes una maceta muy mona en la ventana. Respeto.'::text),
(294827,32759,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... un joli pot de fleurs sur ton rebord de fenêtre. Respect.'::text,'as'::text,'a'::text,'as'::text,'Tu as un joli pot de fleurs sur ton rebord de fenêtre. Respect.'::text),
(294830,32759,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pencere pervazında şirin bir saksın ... Saygı.'::text,'var.'::text,'var.'::text,'var.'::text,'Pencere pervazında şirin bir saksın var. Saygı.'::text),
(294831,32759,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neked ... egy cuki virágcsereped az ablakpárkányon. Respekt.'::text,'van'::text,'van'::text,'van'::text,'Neked van egy cuki virágcsereped az ablakpárkányon. Respekt.'::text),
(294834,32760,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Gewächshaus hat viele ...'::text,'Blumentöpfe.'::text,'Blumentopf.'::text,'Blumentöpfe.'::text,'Das Gewächshaus hat viele Blumentöpfe.'::text),
(294838,32760,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У теплиці багато ...'::text,'вазонів.'::text,'вазон.'::text,'вазонів.'::text,'У теплиці багато вазонів.'::text),
(294837,32760,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El invernadero tiene muchas ...'::text,'macetas.'::text,'maceta.'::text,'macetas.'::text,'El invernadero tiene muchas macetas.'::text),
(294836,32760,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La serre a beaucoup de ...'::text,'pots de fleurs.'::text,'pot de fleurs.'::text,'pots de fleurs.'::text,'La serre a beaucoup de pots de fleurs.'::text),
(294839,32760,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Serada çok ... var.'::text,'saksı'::text,'saksı'::text,'saksı'::text,'Serada çok saksı var.'::text),
(294840,32760,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az üvegházban van sok ...'::text,'virágcserép.'::text,'virágcserép.'::text,'virágcserép.'::text,'Az üvegházban van sok virágcserép.'::text),
(294843,32761,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sieht einen Blumentopf. Er gießt ... Blumentopf.'::text,'den'::text,'einen'::text,'einen'::text,'Er sieht einen Blumentopf. Er gießt den Blumentopf.'::text),
(294847,32761,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він бачить вазон. Він поливає ... вазон.'::text,''::text,NULL::text,NULL::text,'Він бачить вазон. Він поливає вазон.'::text),
(294846,32761,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ve una maceta. Riega ... maceta.'::text,'la'::text,'una'::text,'una'::text,'Ve una maceta. Riega la maceta.'::text),
(294845,32761,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il voit un pot de fleurs. Il arrose ... pot de fleurs.'::text,'le'::text,'un'::text,'un'::text,'Il voit un pot de fleurs. Il arrose le pot de fleurs.'::text),
(294848,32761,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir saksı görüyor. ... saksıyı suluyor.'::text,''::text,'bir'::text,'bir'::text,'Bir saksı görüyor. Saksıyı suluyor.'::text),
(294849,32761,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lát egy virágcserepet. Megöntözi ... virágcserepet.'::text,'a'::text,'egy'::text,'egy'::text,'Lát egy virágcserepet. Megöntözi a virágcserepet.'::text),
(294852,32762,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er gießt ... Blumentopf zuerst.'::text,'diesen'::text,'diese'::text,'jene'::text,'Er gießt diesen Blumentopf zuerst.'::text),
(294856,32762,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він поливає ... вазон першим.'::text,'цей'::text,'ці'::text,'ті'::text,'Він поливає цей вазон першим.'::text),
(294855,32762,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Riega ... maceta primero.'::text,'esta'::text,'estas'::text,'esas'::text,'Riega esta maceta primero.'::text),
(294854,32762,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il arrose ... pot de fleurs en premier.'::text,'ce'::text,'ces'::text,'ces'::text,'Il arrose ce pot de fleurs en premier.'::text),
(294857,32762,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Önce ... saksıyı suluyor.'::text,'bu'::text,'bu'::text,'şu'::text,'Önce bu saksıyı suluyor.'::text),
(294858,32762,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Először ... a virágcserepet öntözi meg.'::text,'ezt'::text,'ezeket'::text,'azokat'::text,'Először ezt a virágcserepet öntözi meg.'::text),
(294870,32764,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Sukkulente ist ... Blumentopf, weil der Blumentopf um sie herum ist.'::text,'im'::text,'auf dem'::text,'am'::text,'Die Sukkulente ist im Blumentopf, weil der Blumentopf um sie herum ist.'::text),
(294874,32764,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сукулент ... вазоні, бо вазон навколо нього.'::text,'у'::text,'на'::text,'біля'::text,'Сукулент у вазоні, бо вазон навколо нього.'::text),
(294873,32764,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La suculenta está ... la maceta porque la maceta está a su alrededor.'::text,'en'::text,'sobre'::text,'a'::text,'La suculenta está en la maceta porque la maceta está a su alrededor.'::text),
(294872,32764,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La plante grasse est ... le pot de fleurs parce que le pot est autour d''elle.'::text,'dans'::text,'sur'::text,'à'::text,'La plante grasse est dans le pot de fleurs parce que le pot est autour d''elle.'::text),
(294875,32764,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sukulent saksının ..., çünkü saksı onun etrafında.'::text,'içinde'::text,'üstünde'::text,NULL::text,'Sukulent saksının içinde, çünkü saksı onun etrafında.'::text),
(294876,32764,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pozsgás a ... van, mert a virágcserép körülötte van.'::text,'virágcserépben'::text,'virágcserépen'::text,'virágcserépnél'::text,'A pozsgás a virágcserépben van, mert a virágcserép körülötte van.'::text),
(294879,32765,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du gibst dem Blumentopf nicht zu ... Wasser. Echt clever.'::text,'viel'::text,'viele'::text,'etwas'::text,'Du gibst dem Blumentopf nicht zu viel Wasser. Echt clever.'::text),
(294883,32765,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти не даєш вазону надто ... води. Чесно, розумно.'::text,'багато'::text,'багато'::text,'трохи'::text,'Ти не даєш вазону надто багато води. Чесно, розумно.'::text),
(294882,32765,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No le das a la maceta ... agua de más. Muy lista, la verdad.'::text,'mucha'::text,'muchas'::text,'algo de'::text,'No le das a la maceta mucha agua de más. Muy lista, la verdad.'::text),
(294881,32765,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ne donnes pas ... eau en trop au pot de fleurs. Franchement malin.'::text,'beaucoup d'''::text,'beaucoup d'''::text,'de l'''::text,'Tu ne donnes pas beaucoup d'' eau en trop au pot de fleurs. Franchement malin.'::text),
(294884,32765,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Saksıya fazla ... su vermiyorsun. Cidden akıllıca.'::text,'çok'::text,'çok'::text,'biraz'::text,'Saksıya fazla çok su vermiyorsun. Cidden akıllıca.'::text),
(294885,32765,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem adsz túl ... vizet a virágcserépnek. Őszintén, okos.'::text,'sok'::text,'sok'::text,'némi'::text,'Nem adsz túl sok vizet a virágcserépnek. Őszintén, okos.'::text),
(326676,36298,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser rote Mantel? Du ... ihn so gut, ehrlich.'::text,'trugst'::text,'trugst'::text,'trägt'::text,'Dieser rote Mantel? Du trugst ihn so gut, ehrlich.'::text),
(326680,36298,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Те червоне пальто? Ти ... його так добре, чесно.'::text,'носила'::text,'носила'::text,'носить'::text,'Те червоне пальто? Ти носила його так добре, чесно.'::text),
(326679,36298,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Ese abrigo rojo? Lo ... genial, en serio.'::text,'llevaste'::text,'llevaste'::text,'lleva'::text,'¿Ese abrigo rojo? Lo llevaste genial, en serio.'::text),
(326678,36298,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce manteau rouge ? Tu ... si bien, franchement.'::text,'l''as porté'::text,'l''as porté'::text,'le porte'::text,'Ce manteau rouge ? Tu l''as porté si bien, franchement.'::text),
(326681,36298,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kırmızı palto mu? Onu o kadar iyi ... ki, cidden.'::text,'giydin'::text,'giydin'::text,'giyer'::text,'O kırmızı palto mu? Onu o kadar iyi giydin ki, cidden.'::text),
(326682,36298,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a piros kabát? Olyan jól ..., komolyan.'::text,'viselted'::text,'viselted'::text,'viseli'::text,'Az a piros kabát? Olyan jól viselted, komolyan.'::text),
(326685,36299,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise trägst du Jeans, aber gestern ... du einen Federhut. Ikonisch.'::text,'trugst'::text,'trägst'::text,NULL::text,'Normalerweise trägst du Jeans, aber gestern trugst du einen Federhut. Ikonisch.'::text),
(326689,36299,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай ти носиш джинси, але вчора ... капелюх із пір''ям. Легенда.'::text,'носила'::text,'носиш'::text,NULL::text,'Зазвичай ти носиш джинси, але вчора носила капелюх із пір''ям. Легенда.'::text),
(326688,36299,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente llevas vaqueros, pero ayer ... un sombrero de plumas. Icónico.'::text,'llevaste'::text,'llevas'::text,NULL::text,'Normalmente llevas vaqueros, pero ayer llevaste un sombrero de plumas. Icónico.'::text),
(326687,36299,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude tu portes un jean, mais hier tu ... un chapeau à plumes. Iconique.'::text,'as porté'::text,'portes'::text,NULL::text,'D''habitude tu portes un jean, mais hier tu as porté un chapeau à plumes. Iconique.'::text),
(326690,36299,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde kot pantolon giyersin ama dün tüylü bir şapka ... İkonik.'::text,'giydin.'::text,'giyersin.'::text,NULL::text,'Genelde kot pantolon giyersin ama dün tüylü bir şapka giydin. İkonik.'::text),
(326691,36299,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában farmert hordasz, de tegnap egy tollas kalapot ... Ikonikus.'::text,'hordtál.'::text,'hordasz.'::text,NULL::text,'Általában farmert hordasz, de tegnap egy tollas kalapot hordtál. Ikonikus.'::text),
(326694,36300,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein total normaler Look, klar: Jetzt ... sie einen riesigen Federmantel.'::text,'trägt'::text,'trägt'::text,'trägt'::text,'Ein total normaler Look, klar: Jetzt trägt sie einen riesigen Federmantel.'::text),
(326698,36300,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже звичайний образ, звісно: зараз вона ... величезне пальто з пір''ям.'::text,'носить'::text,'носить'::text,'носить'::text,'Дуже звичайний образ, звісно: зараз вона носить величезне пальто з пір''ям.'::text),
(326697,36300,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un look muy normal, claro: ahora ... un abrigo enorme de plumas.'::text,'lleva puesto'::text,'lleva'::text,'lleva puesto'::text,'Un look muy normal, claro: ahora lleva puesto un abrigo enorme de plumas.'::text),
(326696,36300,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un look très normal, évidemment : là, elle ... un énorme manteau à plumes.'::text,'porte'::text,'porte'::text,'porte'::text,'Un look très normal, évidemment : là, elle porte un énorme manteau à plumes.'::text),
(326699,36300,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok normal bir tarz, tabii: şimdi kocaman tüylü bir palto ...'::text,'giyiyor'::text,'giyer'::text,'giyiyor'::text,'Çok normal bir tarz, tabii: şimdi kocaman tüylü bir palto giyiyor.'::text),
(326700,36300,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon hétköznapi szett, persze: most egy hatalmas tollas kabátot ...'::text,'visel'::text,'visel'::text,'visel'::text,'Nagyon hétköznapi szett, persze: most egy hatalmas tollas kabátot visel.'::text),
(326703,36301,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise trägt sie Jeans, aber heute ... sie Pailletten. Total unauffällig, klar.'::text,'trägt'::text,'trägt'::text,NULL::text,'Normalerweise trägt sie Jeans, aber heute trägt sie Pailletten. Total unauffällig, klar.'::text),
(326707,36301,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай вона носить джинси, але сьогодні ... паєтки. Дуже скромно, звісно.'::text,'носить'::text,'носить'::text,NULL::text,'Зазвичай вона носить джинси, але сьогодні носить паєтки. Дуже скромно, звісно.'::text),
(326706,36301,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente lleva vaqueros, pero hoy ... lentejuelas. Supersutil, claro.'::text,'lleva puestas'::text,'lleva'::text,NULL::text,'Normalmente lleva vaqueros, pero hoy lleva puestas lentejuelas. Supersutil, claro.'::text),
(326705,36301,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude elle porte un jean, mais aujourd''hui elle ... des paillettes. Hyper discret, évidemment.'::text,'porte'::text,'porte'::text,NULL::text,'D''habitude elle porte un jean, mais aujourd''hui elle porte des paillettes. Hyper discret, évidemment.'::text),
(326708,36301,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde kot pantolon giyer ama bugün payet ... Tabii ki çok sade.'::text,'giyiyor.'::text,'giyer.'::text,NULL::text,'Genelde kot pantolon giyer ama bugün payet giyiyor. Tabii ki çok sade.'::text),
(326709,36301,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában farmert hord, de ma flittereket ... Nyilván visszafogott.'::text,'visel.'::text,'visel.'::text,NULL::text,'Általában farmert hord, de ma flittereket visel. Nyilván visszafogott.'::text),
(326721,36303,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Schlimmste! Sie ... diesen riesigen Federmantel zum Abendessen tragen!'::text,'wird'::text,'werden'::text,'wird'::text,'Das Schlimmste! Sie wird diesen riesigen Federmantel zum Abendessen tragen!'::text),
(326725,36303,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Найгірше! Вона ... вдягнути те величезне пальто з пір''ям на вечерю!'::text,'збирається'::text,'збираються'::text,'збирається'::text,'Найгірше! Вона збирається вдягнути те величезне пальто з пір''ям на вечерю!'::text),
(326724,36303,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Lo peor! ¡Ella ... ponerse ese abrigo de plumas enorme para la cena!'::text,'va a'::text,'van a'::text,'va a'::text,'¡Lo peor! ¡Ella va a ponerse ese abrigo de plumas enorme para la cena!'::text),
(326723,36303,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pire ! Elle ... porter cet énorme manteau à plumes au dîner !'::text,'va'::text,'vont'::text,'va'::text,'Le pire ! Elle va porter cet énorme manteau à plumes au dîner !'::text),
(326726,36303,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En kötüsü! O devasa tüylü paltoyu akşam yemeğine ...!'::text,'giyecek'::text,'giyecekler'::text,'giyecek'::text,'En kötüsü! O devasa tüylü paltoyu akşam yemeğine giyecek!'::text),
(326727,36303,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A legrosszabb! Azt az óriási tollas kabátot ... felvenni a vacsorára!'::text,'fogja'::text,'fogják'::text,'fogja'::text,'A legrosszabb! Azt az óriási tollas kabátot fogja felvenni a vacsorára!'::text),
(326730,36304,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hält den roten Mantel offen. Sie ... ihn als Nächstes tragen.'::text,'wird'::text,'wird'::text,NULL::text,'Sie hält den roten Mantel offen. Sie wird ihn als Nächstes tragen.'::text),
(326734,36304,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона тримає червоне пальто розкритим. Далі вона ... його вдягати.'::text,'збирається'::text,'буде'::text,NULL::text,'Вона тримає червоне пальто розкритим. Далі вона збирається його вдягати.'::text),
(326733,36304,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sostiene abierto el abrigo rojo. Ella ... ponérselo después.'::text,'va a'::text,NULL::text,NULL::text,'Sostiene abierto el abrigo rojo. Ella va a ponérselo después.'::text),
(326732,36304,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle tient le manteau rouge ouvert. Elle ... le porter ensuite.'::text,'va'::text,NULL::text,NULL::text,'Elle tient le manteau rouge ouvert. Elle va le porter ensuite.'::text),
(326735,36304,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kırmızı paltoyu açık tutuyor. Sırada onu ...'::text,'giyecek'::text,'giyecek'::text,NULL::text,'Kırmızı paltoyu açık tutuyor. Sırada onu giyecek.'::text),
(326736,36304,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyitva tartja a piros kabátot. Legközelebb azt ... felvenni.'::text,'fogja'::text,'fogja'::text,NULL::text,'Nyitva tartja a piros kabátot. Legközelebb azt fogja felvenni.'::text),
(313959,34885,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Gerücht geht den langen Tisch entlang.'::text,'Dieses'::text,'Diese'::text,'Jene'::text,'Dieses Gerücht geht den langen Tisch entlang.'::text),
(313963,34885,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... чутка йде вздовж довгого столу.'::text,'Ця'::text,'Ці'::text,'Ті'::text,'Ця чутка йде вздовж довгого столу.'::text),
(313962,34885,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... rumor recorre la mesa larga.'::text,'Este'::text,'Estos'::text,'Esos'::text,'Este rumor recorre la mesa larga.'::text),
(313961,34885,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... rumeur circule le long de la grande table.'::text,'Cette'::text,'Ces'::text,'Ces'::text,'Cette rumeur circule le long de la grande table.'::text),
(313964,34885,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... söylenti uzun masa boyunca dolaşıyor.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu söylenti uzun masa boyunca dolaşıyor.'::text),
(313965,34885,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a pletyka végigmegy a hosszú asztalon.'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez a pletyka végigmegy a hosszú asztalon.'::text),
(313968,34886,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Junge mit der Krawatte flüstert ... Gerücht.'::text,'sein'::text,'ihr'::text,'sein'::text,'Der Junge mit der Krawatte flüstert sein Gerücht.'::text),
(313972,34886,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопець у краватці шепоче ... чутку.'::text,'свою'::text,'її'::text,'його'::text,'Хлопець у краватці шепоче свою чутку.'::text),
(313971,34886,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El chico de la corbata susurra ... rumor.'::text,'su'::text,'su'::text,'su'::text,'El chico de la corbata susurra su rumor.'::text),
(313970,34886,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le garçon à la cravate chuchote ... rumeur.'::text,'sa'::text,'sa'::text,'sa'::text,'Le garçon à la cravate chuchote sa rumeur.'::text),
(313973,34886,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kravatlı çocuk ... söylentisini fısıldıyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Kravatlı çocuk onun söylentisini fısıldıyor.'::text),
