(314004,34890,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das schlimmste Gerücht aller Zeiten! So ... Schüler lachen!'::text,'viele'::text,'viel'::text,'ein bisschen'::text,'Das schlimmste Gerücht aller Zeiten! So viele Schüler lachen!'::text),
(314008,34890,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Найгірша чутка в історії! Так ... студентів сміється!'::text,'багато'::text,'багато'::text,'трохи'::text,'Найгірша чутка в історії! Так багато студентів сміється!'::text),
(314007,34890,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El peor rumor de la historia! ¡Madre mía, ... estudiantes se están riendo!'::text,'muchos'::text,'mucho'::text,'un poco de'::text,'¡El peor rumor de la historia! ¡Madre mía, muchos estudiantes se están riendo!'::text),
