(314009,34890,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tüm zamanların en kötü söylentisi! O kadar ... öğrenci gülüyor ki!'::text,'çok'::text,'çok'::text,'biraz'::text,'Tüm zamanların en kötü söylentisi! O kadar çok öğrenci gülüyor ki!'::text),
